/* ===== syllabus alignment: objectives per lesson (SYL) and gap-fill sections (GAP) ===== */
const SYL={"chem":{"1.1":[["1.1.1","State the distinguishing properties of solids, liquids and gases",0],["1.1.2","Describe the structures of solids, liquids and gases in terms of particle separation, arrangement and motion",0],["1.1.6","Explain, in terms of kinetic particle theory, the effects of temperature and pressure on the volume of a gas",1]],"1.2":[["1.1.3","Describe changes of state in terms of melting, boiling, evaporating, freezing and condensing",0],["1.1.5","Explain changes of state in terms of kinetic particle theory, including the interpretation of heating and cooling curves",1]],"1.3":[["1.1.4","Describe the effects of temperature and pressure on the volume of a gas",0]],"1.4":[["1.2.1","Describe and explain diffusion in terms of kinetic particle theory",0],["1.2.2","Describe and explain the effect of relative molecular mass on the rate of diffusion of gases",1]],"2.1":[["2.1.1","Describe the differences between elements, compounds and mixtures",0],["2.2.1","Describe the structure of the atom as a central nucleus containing neutrons and protons surrounded by electrons in shells",0],["2.2.2","State the relative charges and relative masses of a proton, a neutron and an electron",0],["2.2.3","Define proton number / atomic number as the number of protons in the nucleus of an atom",0],["2.2.4","Define mass number / nucleon number as the total number of protons and neutrons in the nucleus of an atom",0],["2.2.5","Determine the electronic configuration of elements and their ions with proton number 1 to 20, e.g. 2,8,3",0],["2.2.6","State that: (a) Group VIII noble gases have a full outer electron shell (b) the number of outer shell electrons is equal to the group number in Groups I to VII (c) the number of occupied electron shells is equal to the period number",0],["2.3.1","Define isotopes as different atoms of the same element that have the same number of protons but different numbers of neutrons",0],["2.3.2","Interpret and use symbols for atoms, e.g. ¹²₆C, and ions, e.g. ³⁵₁₇Cl⁻",0],["2.3.3","State that isotopes of the same element have the same chemical properties because they have the same number of electrons and therefore the same electronic configuration",1],["2.3.4","Calculate the relative atomic mass of an element from the relative masses and abundances of its isotopes",1]],"2.2":[["2.4.1","Describe the formation of positive ions, known as cations, and negative ions, known as anions",0],["2.4.2","State that an ionic bond is a strong electrostatic attraction between oppositely charged ions",0],["2.4.3","Describe the formation of ionic bonds between elements from Group I and Group VII, including the use of dot-and-cross diagrams",0],["2.4.5","Describe the giant lattice structure of ionic compounds as a regular arrangement of alternating positive and negative ions",1],["2.5.4","Describe the formation of covalent bonds in simple molecules, including CH₃OH, C₂H₄, O₂, CO₂and N₂. Use dot-and-cross diagrams to show the electronic configurations in these and similar molecules",1]],"2.5":[["2.4.4","Describe the properties of ionic compounds: (a) h igh melting points and boiling points (b) g ood electrical conductivity when aqueous or molten and poor when solid",0],["2.4.7","Explain in terms of structure and bonding the properties of ionic compounds: (a) high melting points and boiling points (b) g ood electrical conductivity when aqueous or molten and poor when solid",1],["2.5.3","Describe in terms of structure and bonding the properties of simple molecular compounds: (a) low melting points and boiling points (b) poor electrical conductivity",0],["2.5.5","Explain in terms of structure and bonding the properties of simple molecular compounds: (a) low melting points and boiling points in terms of weak intermolecular forces (specific types of intermolecular forces are not required) (b) poor electrical conductivity",1],["2.7.1","Describe metallic bonding as the electrostatic attraction between the positive ions in a giant metallic lattice and a ‘sea’ of delocalised electrons",1],["2.7.2","Explain in terms of structure and bonding the properties of metals: (a) good electrical conductivity (b) malleability and ductility",1]],"2.3":[["2.4.6","Describe the formation of ionic bonds between ions of metallic and non-metallic elements, including the use of dot-and-cross diagrams",1],["2.5.1","State that a covalent bond is formed when a pair of electrons is shared between two atoms leading to noble gas electronic configurations",0],["2.5.2","Describe the formation of covalent bonds in simple molecules, including H₂, Cl₂, H₂O, CH₄, NH₃and HCl. Use dot-and-cross diagrams to show the electronic configurations in these and similar molecules",0]],"2.4":[["2.6.1","Describe the giant covalent structures of graphite and diamond",0],["2.6.2","Relate the structures and bonding of graphite and diamond to their uses, limited to: (a) graphite as a lubricant and as an electrode (b) diamond in cutting tools",0],["2.6.3","Describe the giant covalent structure of silicon(IV) oxide, SiO₂",1],["2.6.4","Describe the similarity in properties between diamond and silicon(IV) oxide, related to their structures",1]],"3.2":[["3.1.1","State the formulae of the elements and compounds named in the subject content",0],["3.1.4","Construct word equations and symbol equations to show how reactants form products, including state symbols",0],["3.1.8","Deduce the symbol equation with state symbols for a chemical reaction, given relevant information",1]],"3.1":[["3.1.2","Define the molecular formula of a compound as the number and type of different atoms in one molecule",0],["3.1.5","Define the empirical formula of a compound as the simplest whole number ratio of the different atoms or ions in a compound",1],["3.1.6","Deduce the formula of an ionic compound from the relative numbers of the ions present in a model or a diagrammatic representation or from the charges on the ions",1],["3.1.7","Construct symbol equations with state symbols, including ionic equations",1],["3.3.7","Calculate empirical formulae and molecular formulae, given appropriate data",1]],"3.7":[["3.1.3","Deduce the formula of a simple compound from the relative numbers of atoms present in a model or a diagrammatic representation",0],["3.3.8","Calculate percentage yield, percentage composition by mass and percentage purity, given appropriate data",1]],"3.3":[["3.2.1","Describe relative atomic mass, A, as the r average mass of the isotopes of an element compared to 1/12th of the mass of an atom of C",0],["3.2.2","Define relative molecular mass, M, as the sum r of the relative atomic masses. Relative formula mass, M, will be used for ionic compounds r",0]],"3.5":[["3.2.3","Calculate reacting masses in simple proportions. Calculations will not involve the mole concept",0],["3.3.4","Use the molar gas volume, taken as 24 dm³at room temperature and pressure, r.t.p., in calculations involving gases",1]],"3.6":[["3.3.1","State that concentration can be measured in g / dm³ or mol / dm³",0],["3.3.5","Calculate stoichiometric reacting masses, limiting reactants, volumes of gases at r.t.p., volumes of solutions and concentrations of solutions expressed in g / dm³and mol / dm³, including conversion between cm₃and dm³",1],["3.3.6","Use experimental data from a titration to calculate the moles of solute, or the concentration or volume of a solution",1]],"3.4":[["3.3.2","State that the mole, mol, is the unit of amount of substance and that one mole contains 6.02 × 10₂₃particles, e.g. atoms, ions, molecules; this number is the Avogadro constant",1],["3.3.3","Use the relationship mass (g) amount of substance (mol) = molar mass (g / mol) to calculate: (a) amount of substance (b) mass (c) molar mass (d) relative atomic mass or relative molecular / formula mass (e) number of particles, using the value of the Avogadro constant",1]],"4.1":[["4.1.1","Define electrolysis as the decomposition of an ionic compound, when molten or in aqueous solution, by the passage of an electric current",0],["4.1.4","State that metals or hydrogen are formed at the cathode and that non-metals (other than hydrogen) are formed at the anode",0],["4.1.5","Predict the identity of the products at each electrode for the electrolysis of a binary compound in the molten state",0],["4.1.11","Construct ionic half-equations for reactions at the anode (to show oxidation) and at the cathode (to show reduction)",1]],"4.2":[["4.1.2","Identify in simple electrolytic cells: (a) the anode as the positive electrode (b) the cathode as the negative electrode (c) the electrolyte as the molten or aqueous substance that undergoes electrolysis",0],["4.1.3","Identify the products formed at the electrodes and describe the observations made during the electrolysis of: (a) molten lead(II) bromide (b) concentrated aqueous sodium chloride (c) dilute sulfuric acid using inert electrodes made of platinum or carbon / graphite",0],["4.1.9","Identify the products formed at the electrodes and describe the observations made during the electrolysis of aqueous copper(II) sulfate using inert carbon / graphite electrodes and when using copper electrodes",1],["4.1.10","Predict the identity of the products at each electrode for the electrolysis of a halide compound in dilute or concentrated aqueous solution",1]],"4.3":[["4.1.6","State that metal objects are electroplated to improve their appearance and resistance to corrosion",0],["4.1.7","Describe how metals are electroplated",0]],"4.4":[["4.1.8","Describe the transfer of charge during electrolysis to include: (a) the movement of electrons in the external circuit (b) the loss or gain of electrons at the electrodes (c) the movement of ions in the electrolyte",1],["4.2.1","State that a hydrogen–oxygen fuel cell uses hydrogen and oxygen to produce electricity with water as the only chemical product",0],["4.2.2","Describe the advantages and disadvantages of using hydrogen–oxygen fuel cells in comparison with gasoline / petrol engines in vehicles",1]],"5.1":[["5.1.1","State that an exothermic reaction transfers thermal energy to the surroundings leading to an increase in the temperature of the surroundings",0],["5.1.2","State that an endothermic reaction takes in thermal energy from the surroundings leading to a decrease in the temperature of the surroundings",0],["5.1.4","State that the transfer of thermal energy during a reaction is called the enthalpy change, ∆ H, of the reaction. ∆ H is negative for exothermic reactions and positive for endothermic reactions",1]],"5.2":[["5.1.3","Interpret reaction pathway diagrams showing exothermic and endothermic reactions",0],["5.1.5","Define activation energy, E, as the minimum a energy that colliding particles must have to react",1],["5.1.6","Draw and label reaction pathway diagrams for exothermic and endothermic reactions using information provided, to include: (a) reactants (b) products (c) enthalpy change of the reaction, ∆ H (d) activation energy, E a",1]],"5.3":[["5.1.7","State that bond breaking is an endothermic process and bond making is an exothermic process and explain the enthalpy change of a reaction in terms of bond breaking and bond making",1],["5.1.8","Calculate the enthalpy change of a reaction using bond energies",1]],"6.1":[["6.1.1","Identify physical and chemical changes, and describe the differences between them",0]],"6.2":[["6.2.1","Describe the effect on the rate of reaction of: (a) changing the concentration of solutions (b) changing the pressure of gases (c) changing the surface area of solids (d) changing the temperature (e) adding or removing a catalyst, including enzymes",0],["6.2.2","State that a catalyst increases the rate of a reaction and is unchanged at the end of a reaction",0],["6.2.5","Describe collision theory in terms of: (a) number of particles per unit volume (b) frequency of collisions between particles (c) kinetic energy of particles (d) activation energy, E a",1],["6.2.6","Describe and explain the effect on the rate of reaction of: (a) changing the concentration of solutions (b) changing the pressure of gases (c) changing the surface area of solids (d) changing the temperature (e) adding or removing a catalyst, including enzymes using collision theory",1],["6.2.7","State that a catalyst decreases the activation energy, E, of a reaction a",1]],"6.3":[["6.2.3","Describe practical methods for investigating the rate of a reaction including change in mass of a reactant or a product and the formation of a gas",0],["6.2.4","Interpret data, including graphs, from rate of reaction experiments",0],["6.2.8","Evaluate practical methods for investigating the rate of a reaction including change in mass of a reactant or a product and the formation of a gas",1]],"6.4":[["6.3.1","State that some chemical reactions are reversible as shown by the symbol ⇌",0],["6.3.2","Describe how changing the conditions can change the direction of a reversible reaction for: (a) the effect of heat on hydrated compounds (b) the addition of water to anhydrous compounds limited to copper(II) sulfate and cobalt(II) chloride",0],["6.3.5","State the symbol equation for the production of ammonia in the Haber process, N₂(g) + 3H₂(g) 2NH₃(g)",1]],"6.5":[["6.3.3","State that a reversible reaction in a closed system is at equilibrium when: (a) the rate of the forward reaction is equal to the rate of the reverse reaction (b) the concentrations of reactants and products are no longer changing",1],["6.3.4","Predict and explain, for a reversible reaction, how the position of equilibrium is affected by: (a) changing temperature (b) changing pressure (c) changing concentration (d) using a catalyst using information provided",1]],"6.6":[["6.3.6","State the sources of the hydrogen (methane) ⇌ and nitrogen (air) in the Haber process",1],["6.3.7","State the typical conditions in the Haber process as 450 °C, 20 000 kPa / 200 atm and an iron catalyst",1],["6.3.8","State the symbol equation for the conversion of sulfur dioxide to sulfur trioxide in the Contact process, 2SO₂(g) + O₂(g) 2SO₃(g)",1],["6.3.9","State the sources of the sulfur dioxide (burning ⇌ sulfur or roasting sulfide ores) and oxygen (air) in the Contact process",1],["6.3.10","State the typical conditions for the conversion of sulfur dioxide to sulfur trioxide in the Contact process as 450 °C, 200 kPa / 2 atm and a vanadium(V) oxide catalyst",1],["6.3.11","Explain, in terms of rate of reaction and position of equilibrium, why the typical conditions stated are used in the Haber process and in the Contact process, including safety considerations and economics",1]],"6.7":[["6.4.1","Use a Roman numeral to indicate the oxidation number of an element in a compound",0],["6.4.2","Define redox reactions as involving simultaneous oxidation and reduction",0],["6.4.3","Define oxidation as gain of oxygen and reduction as loss of oxygen",0],["6.4.4","Identify redox reactions as reactions involving gain and loss of oxygen",0],["6.4.5","Identify oxidation and reduction in redox reactions",0],["6.4.6","Define oxidation in terms of: (a) loss of electrons (b) an increase in oxidation number",1],["6.4.7","Define reduction in terms of: (a) gain of electrons (b) a decrease in oxidation number",1],["6.4.8","Identify redox reactions as reactions involving gain and loss of electrons",1],["6.4.9","Identify redox reactions by changes in oxidation number using: (a) the oxidation number of elements in their uncombined state is zero (b) the oxidation number of a monatomic ion is the same as the charge on the ion (c) the sum of the oxidation numbers in a compound is zero (d) the sum of the oxidation numbers in an ion is equal to the charge on the ion",1]],"6.8":[["6.4.10","Identify redox reactions by the colour changes involved when using acidified aqueous potassium manganate(VII) or aqueous potassium iodide",1],["6.4.11","Define an oxidising agent as a substance that oxidises another substance and is itself reduced",1],["6.4.12","Define a reducing agent as a substance that reduces another substance and is itself oxidised",1],["6.4.13","Identify oxidising agents and reducing agents in redox reactions",1]],"7.1":[["7.1.1","Describe the characteristic properties of acids in terms of their reactions with: (a) metals (b) bases (c) carbonates",0],["7.1.2","Describe acids in terms of their effect on: (a) litmus (b) thymolphthalein (c) methyl orange",0],["7.1.3","State that bases are oxides or hydroxides of metals and that alkalis are soluble bases",0],["7.1.4","Describe the characteristic properties of bases in terms of their reactions with: (a) acids (b) ammonium salts",0],["7.1.5","Describe alkalis in terms of their effect on: (a) litmus (b) thymolphthalein (c) methyl orange",0],["7.1.6","State that aqueous solutions of acids contain H⁺ions and aqueous solutions of alkalis contain OH⁻ions",0],["7.1.8","Describe the neutralisation reaction between an acid and an alkali to produce water, H⁺ (aq) + OH⁻ (aq) → H₂O (l)",0]],"7.2":[["7.1.7","Describe how to compare hydrogen ion concentration, neutrality, relative acidity and relative alkalinity in terms of colour and pH using universal indicator paper",0],["7.1.9","Define acids as proton donors and bases as proton acceptors",1],["7.1.10","Define a strong acid as an acid that is completely dissociated in aqueous solution and a weak acid as an acid that is partially dissociated in aqueous solution",1],["7.1.11","State that hydrochloric acid is a strong acid, as shown by the symbol equation, HCl (aq) → H⁺ (aq) + Cl⁻ (aq)",1],["7.1.12","State that ethanoic acid is a weak acid, as shown by the symbol equation, CH₃COOH(aq) H⁺ (aq) + CH₃COO⁻ (aq) ⇌",1]],"7.3":[["7.2.1","Classify oxides as acidic, including SO₂and CO₂, or basic, including CuO and CaO, related to metallic and non-metallic character",0],["7.2.2","Describe amphoteric oxides as oxides that react with acids and with bases to produce a salt and water",1],["7.2.3","Classify Al₂O₃and ZnO as amphoteric oxides",1]],"7.4":[["7.3.1","Describe the preparation, separation and purification of soluble salts by reaction of an acid with: (a) an alkali by titration (b) excess metal (c) excess insoluble base (d) excess insoluble carbonate",0]],"7.5":[["7.3.2","Describe the general solubility rules for salts: (a) s odium, potassium and ammonium salts are soluble (b) nitrates are soluble (c) chlorides are soluble, except lead and silver (d) sulfates are soluble, except barium, calcium and lead (e) carbonates are insoluble, except sodium, potassium and ammonium (f) hydroxides are insoluble, except sodium, potassium, ammonium and calcium (partially)",0],["7.3.3","Define a hydrated substance as a substance that is chemically combined with water and an anhydrous substance as a substance containing no water",0],["7.3.4","Describe the preparation of insoluble salts by precipitation",1],["7.3.5","Define the term water of crystallisation as the water molecules present in hydrated crystals, including CuSO₄ •5H₂O and CoCl₂ •6H₂O",1]],"8.1":[["8.1.1","Describe the Periodic Table as an arrangement of elements in periods and groups and in order of increasing proton number / atomic number",0],["8.1.2","Describe the change from metallic to non-metallic character across a period",0],["8.1.4","Explain similarities in the chemical properties of elements in the same group of the Periodic Table in terms of their electronic configuration",0],["8.1.5","Explain how the position of an element in the Periodic Table can be used to predict its properties",0],["8.1.6","Identify trends in groups, given information about the elements",1],["8.2.2","Predict the properties of other elements in Group I, given information about the elements",0],["8.3.4","Predict the properties of other elements in Group VII, given information about the elements",0]],"8.3":[["8.1.3","Describe the relationship between group number and the charge of the ions formed from elements in that group",0],["8.3.1","Describe the Group VII halogens, chlorine, bromine and iodine, as diatomic non-metals with general trends down the group, limited to: (a) increasing density (b) decreasing reactivity",0],["8.3.2","State the appearance of the halogens at r.t.p. as: (a) chlorine, a pale yellow-green gas (b) bromine, a red-brown liquid (c) iodine, a grey-black solid",0],["8.3.3","Describe and explain the displacement reactions of halogens with other halide ions",0]],"8.2":[["8.2.1","Describe the Group I alkali metals, lithium, sodium and potassium, as relatively soft metals with general trends down the group, limited to: (a) decreasing melting point (b) increasing density (c) increasing reactivity",0]],"8.4":[["8.4.1","Describe the transition elements as metals that: (a) have high densities (b) have high melting points (c) form coloured compounds (d) often act as catalysts as elements and in compounds",0],["8.4.2","Describe transition elements as having ions with variable oxidation numbers, including iron(II) and iron(III)",1],["8.5.1","Describe the Group VIII noble gases as unreactive, monatomic gases and explain this in terms of electronic configuration",0]],"9.1":[["9.1.1","Compare the general physical properties of metals and non-metals, including: (a) thermal conductivity (b) electrical conductivity (c) malleability and ductility (d) melting points and boiling points",0],["9.1.2","Describe the general chemical properties of metals, limited to their reactions with: (a) dilute acids (b) cold water and steam (c) oxygen",0],["9.2.1","Describe the uses of metals in terms of their physical properties, including: (a) aluminium in the manufacture of aircraft because of its low density (b) aluminium in the manufacture of overhead electrical cables because of its low density and good electrical conductivity (c) aluminium in food containers because of its resistance to corrosion (d) copper in electrical wiring because of its good electrical conductivity and ductility",0],["9.3.1","Describe an alloy as a mixture of a metal with other elements, including: (a) brass as a mixture of copper and zinc (b) stainless steel as a mixture of iron and other elements such as chromium, nickel and carbon",0],["9.3.2","State that alloys can be harder and stronger than the pure metals and are more useful",0],["9.3.3","Describe the uses of alloys in terms of their physical properties, including stainless steel in cutlery because of its hardness and resistance to rusting",0],["9.3.4","Identify representations of alloys from diagrams of structure",0],["9.3.5","Explain in terms of structure how alloys can be harder and stronger than the pure metals because the different sized atoms in alloys mean the layers can no longer slide over each other",1],["9.4.5","Explain the apparent unreactivity of aluminium in terms of its oxide layer",1]],"9.2":[["9.4.1","State the order of the reactivity series as: potassium, sodium, calcium, magnesium, aluminium, carbon, zinc, iron, hydrogen, copper, silver, gold",0],["9.4.2","Describe the reactions, if any, of: (a) potassium, sodium and calcium with cold water (b) magnesium with steam (c) magnesium, zinc, iron, copper, silver and gold with dilute hydrochloric acid and explain these reactions in terms of the position of the metals in the reactivity series",0],["9.4.3","Deduce an order of reactivity from a given set of experimental results",0],["9.4.4","Describe the relative reactivities of metals in terms of their tendency to form positive ions, by displacement reactions, if any, with the aqueous ions of magnesium, zinc, iron, copper and silver",1],["9.5.1","State the conditions required for the rusting of iron and steel to form hydrated iron(III) oxide",0],["9.5.2","State some common barrier methods, including painting, greasing and coating with plastic",0],["9.5.3","Describe how barrier methods prevent rusting by excluding oxygen or water",0],["9.5.4","Describe the use of zinc in galvanising as an example of a barrier method and sacrificial protection",1],["9.5.5","Explain sacrificial protection in terms of the reactivity series and in terms of electron loss",1]],"9.3":[["9.6.1","Describe the ease in obtaining metals from their ores, related to the position of the metal in the reactivity series",0],["9.6.2","Describe the extraction of iron from hematite in the blast furnace, limited to: (a) the burning of carbon (coke) to provide heat and produce carbon dioxide (b) the reduction of carbon dioxide to carbon monoxide (c) the reduction of iron(III) oxide by carbon monoxide (d) the thermal decomposition of calcium carbonate / limestone to produce calcium oxide (e) the formation of slag Symbol equations are not required",0],["9.6.3","State that the main ore of aluminium is bauxite and that aluminium is extracted by electrolysis",0],["9.6.4","State the symbol equations for the extraction of iron from hematite (a) C + O₂ → CO₂(b) C + CO₂ → 2CO (c) Fe₂O₃ + 3CO → 2Fe + 3CO₂(d) CaCO₃ → CaO + CO₂(e) CaO + SiO₂ → CaSiO₃",1],["9.6.5","Describe the extraction of aluminium from purified bauxite / aluminium oxide, including: (a) the role of cryolite (b) why the carbon anodes need to be regularly replaced (c) the reactions at the electrodes, including ionic half-equations Details of the purification of bauxite are not required",1]],"10.1":[["10.1.1","Describe chemical tests for the presence of water using anhydrous cobalt(II) chloride and anhydrous copper(II) sulfate",0],["10.1.2","Describe how to test for the purity of water using melting point and boiling point",0],["10.1.3","Explain that distilled water is used in practical chemistry rather than tap water because it contains fewer chemical impurities",0],["10.1.4","State that water from natural sources may contain substances, including: (a) dissolved oxygen (b) metal compounds (c) plastics (d) sewage (e) harmful microbes (f) nitrates from fertilisers (g) phosphates from fertilisers and detergents",0],["10.1.5","State that some of these substances are beneficial, including: (a) dissolved oxygen for aquatic life (b) some metal compounds provide essential minerals for life",0],["10.1.6","State that some of these substances are potentially harmful, including: (a) some metal compounds are toxic (b) some plastics harm aquatic life (c) s ewage contains harmful microbes which cause disease (d) nitrates and phosphates lead to deoxygenation of water and damage to aquatic life Details of the eutrophication process are not required",0],["10.1.7","Describe the treatment of the domestic water supply in terms of: (a) sedimentation and filtration to remove solids (b) use of carbon to remove tastes and odours (c) chlorination to kill microbes",0],["10.2.1","State that ammonium salts and nitrates are used as fertilisers",0],["10.2.2","Describe the use of NPK fertilisers to provide the elements nitrogen, phosphorus and potassium for improved plant growth",0]],"10.2":[["10.3.1","State the composition of clean, dry air as approximately 78% nitrogen, N₂, 21% oxygen, O₂and the remainder as a mixture of noble gases and carbon dioxide, CO₂",0],["10.3.8","Explain how oxides of nitrogen form in car engines and describe their removal by catalytic converters, e.g. 2CO + 2NO → 2CO₂ + N₂",1]],"10.3":[["10.3.2","State the source of each of these air pollutants, limited to: (a) carbon dioxide from the complete combustion of carbon-containing fuels (b) carbon monoxide and particulates from the incomplete combustion of carbon- containing fuels (c) m ethane from the decomposition of vegetation and waste gases from digestion in animals (d) oxides of nitrogen from car engines (e) sulfur dioxide from the combustion of fossil fuels which contain sulfur compounds",0],["10.3.3","State the adverse effect of these air pollutants, limited to: (a) carbon dioxide: higher levels of carbon dioxide leading to increased global warming, which leads to climate change (b) carbon monoxide: toxic gas (c) particulates: increased risk of respiratory problems and cancer (d) methane: higher levels of methane leading to increased global warming, which leads to climate change (e) oxides of nitrogen: acid rain, photochemical smog and respiratory problems (f) sulfur dioxide: acid rain",0],["10.3.7","Describe how the greenhouse gases carbon dioxide and methane cause global warming, limited to: (a) the absorption, reflection and emission of thermal energy (b) reducing thermal energy loss to space",1]],"10.4":[["10.3.4","State and explain strategies to reduce the effects of these environmental issues, limited to: (a) climate change: planting trees, reduction in livestock farming, decreasing use of fossil fuels, increasing use of hydrogen and renewable energy, e.g. wind, solar (b) acid rain: use of catalytic converters in vehicles, reducing emissions of sulfur dioxide by using low-sulfur fuels and flue gas desulfurisation with calcium oxide",0]],"10.5":[["10.3.5","Describe photosynthesis as the reaction between carbon dioxide and water to produce glucose and oxygen in the presence of chlorophyll and using energy from light",0],["10.3.6","State the word equation for photosynthesis, carbon dioxide + water → glucose + oxygen",0],["10.3.9","State the symbol equation for photosynthesis, 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂",1]],"11.1":[["11.1.1","Draw and interpret the displayed formula of a molecule to show all the atoms and all the bonds",0],["11.1.2","Write and interpret general formulae of compounds in the same homologous series, limited to: (a) alkanes, C H n 2n+2 (b) alkenes, C H n 2n (c) alcohols, C H OH n 2n+1 (d) carboxylic acids, C H COOH n 2n+1",0],["11.1.3","Identify a functional group as an atom or group of atoms that determine the chemical properties of a homologous series",0],["11.1.4","State that a homologous series is a family of similar compounds with similar chemical properties due to the presence of the same functional group",0],["11.1.5","State that a saturated compound has molecules in which all carbon–carbon bonds are single bonds",0],["11.1.6","State that an unsaturated compound has molecules in which one or more carbon– carbon bonds are not single bonds",0],["11.1.7","State that a structural formula is an unambiguous description of the way the atoms in a molecule are arranged, including CH₂ =CH₂, CH₃CH₂OH, CH₃COOCH₃",1],["11.1.8","Define structural isomers as compounds with the same molecular formula, but different structural formulae, including C₄H₁₀as CH₃CH₂CH₂CH₃and CH₃CH(CH₃)CH₃and C₄H₈as CH₃CH₂CH=CH₂and CH₃CH=CHCH₃",1],["11.1.9","Describe the general characteristics of a homologous series as: (a) having the same functional group (b) having the same general formula (c) differing from one member to the next by a –CH₂ – unit (d) displaying a trend in physical properties (e) sharing similar chemical properties",1],["11.2.1","Name and draw the displayed formulae of: (a) methane and ethane (b) ethene (c) ethanol (d) ethanoic acid (e) the products of the reactions stated in sections 11.4–11.7",0],["11.2.2","State the type of compound present, given a chemical name ending in -ane, -ene, -ol, or -oic acid or from a molecular formula or displayed formula",0],["11.2.3","Name and draw the structural and displayed formulae of unbranched: (a) alkanes (b) a lkenes, including but-1-ene and but-2-ene (c) a lcohols, including propan-1-ol, propan-2-ol, butan-1-ol and butan-2-ol (d) carboxylic acids containing up to four carbon atoms per molecule",1],["11.2.4","Name and draw the displayed formulae of the unbranched esters which can be made from unbranched alcohols and carboxylic acids, each containing up to four carbon atoms",1],["11.3.3","State that hydrocarbons are compounds that contain hydrogen and carbon only",0],["11.4.1","State that the bonding in alkanes is single covalent and that alkanes are saturated hydrocarbons",0],["11.5.1","State that the bonding in alkenes includes a double carbon–carbon covalent bond and that alkenes are unsaturated hydrocarbons",0]],"11.2":[["11.3.1","Name the fossil fuels: coal, natural gas and petroleum",0],["11.3.2","Name methane as the main constituent of natural gas",0],["11.3.4","State that petroleum is a mixture of hydrocarbons",0],["11.3.5","Describe the separation of petroleum into useful fractions by fractional distillation",0],["11.3.6","Describe how the properties of fractions obtained from petroleum change from the bottom to the top of the fractionating column, limited to: (a) decreasing chain length (b) higher volatility (c) lower boiling points (d) lower viscosity",0],["11.3.7","Name the uses of the fractions as: (a) refinery gas fraction for gas used in heating and cooking (b) gasoline / petrol fraction for fuel used in cars (c) naphtha fraction as a chemical feedstock (d) kerosene / paraffin fraction for jet fuel (e) diesel oil / gas oil fraction for fuel used in diesel engines (f) fuel oil fraction for fuel used in ships and home heating systems (g) lubricating oil fraction for lubricants, waxes and polishes (h) bitumen fraction for making roads",0]],"11.3":[["11.4.2","Describe the properties of alkanes as being generally unreactive, except in terms of combustion and substitution by chlorine",0],["11.4.3","State that in a substitution reaction one atom or group of atoms is replaced by another atom or group of atoms",1],["11.4.4","Describe the substitution reaction of alkanes with chlorine as a photochemical reaction, with ultraviolet light providing the activation energy, E, and draw the structural or a displayed formulae of the products, limited to monosubstitution",1]],"11.4":[["11.5.2","Describe the manufacture of alkenes and hydrogen by the cracking of larger alkane molecules using a high temperature and a catalyst",0],["11.5.3","Describe the reasons for the cracking of larger alkane molecules",0],["11.5.4","Describe the test to distinguish between saturated and unsaturated hydrocarbons by their reaction with aqueous bromine",0],["11.5.5","State that in an addition reaction only one product is formed",1],["11.5.6","Describe the properties of alkenes in terms of addition reactions with: (a) bromine or aqueous bromine (b) hydrogen in the presence of a nickel catalyst (c) steam in the presence of an acid catalyst and draw the structural or displayed formulae of the products",1]],"11.5":[["11.6.1","Describe the manufacture of ethanol by: (a) fermentation of aqueous glucose at 25– 35 °C in the presence of yeast and in the absence of oxygen (b) catalytic addition of steam to ethene at 300 °C and 6000 kPa / 60 atm in the presence of an acid catalyst",0],["11.6.2","Describe the combustion of ethanol",0],["11.6.3","State the uses of ethanol as: (a) a solvent (b) a fuel",0],["11.6.4","Describe the advantages and disadvantages of the manufacture of ethanol by: (a) fermentation (b) catalytic addition of steam to ethene",1]],"11.6":[["11.7.1","Describe the reaction of ethanoic acid with: (a) metals (b) bases (c) carbonates including names and formulae of the salts produced",0],["11.7.2","Describe the formation of ethanoic acid by the oxidation of ethanol: (a) w ith acidified aqueous potassium manganate(VII) (b) b y bacterial oxidation during vinegar production",1],["11.7.3","Describe the reaction of a carboxylic acid with an alcohol using an acid catalyst to form an ester",1]],"11.7":[["11.8.1","Define polymers as large molecules built up from many smaller molecules called monomers",0],["11.8.2","Describe the formation of poly(ethene) as an example of addition polymerisation using ethene monomers",0],["11.8.3","State that plastics are made from polymers",0],["11.8.4","Describe how the properties of plastics have implications for their disposal",0],["11.8.5","Describe the environmental challenges caused by plastics, limited to: (a) disposal in landfill sites (b) accumulation in oceans (c) formation of toxic gases from burning",0],["11.8.6","Identify the repeat units and / or linkages in addition polymers and in condensation polymers",1],["11.8.7","Deduce the structure or repeat unit of an addition polymer from a given alkene and vice versa",1],["11.8.8","Deduce the structure or repeat unit of a condensation polymer from given monomers and vice versa, limited to: (a) polyamides from a dicarboxylic acid and a diamine (b) polyesters from a dicarboxylic acid and a diol",1],["11.8.9","Describe the differences between addition and condensation polymerisation",1],["11.8.10","Describe and draw the structure of: (a) nylon, a polyamide O O O O C N N C C N N C H H H H (b) PET, a polyester O O O O C C O O C C O O The full name for PET, polyethylene terephthalate, is not required",1],["11.8.11","State that PET can be converted back into monomers and re-polymerised",1],["11.8.12","Describe proteins as natural polyamides and that they are formed from amino acid monomers with the general structure: R O H N C C H O H H where R represents different types of side- chain",1],["11.8.13","Describe and draw the structure of proteins as: H O H O N C N C N C",1]],"12.1":[["12.1.1","Name appropriate apparatus for the measurement of time, temperature, mass and volume, including: (a) stop-watches (b) thermometers (c) balances (d) burettes (e) volumetric pipettes (f) measuring cylinders (g) gas syringes",0],["12.1.2","Suggest advantages and disadvantages of experimental methods and apparatus",0],["12.2.1","Describe an acid–base titration to include the use of a: (a) burette (b) volumetric pipette (c) suitable indicator",0]],"12.4":[["12.1.3","Describe a: (a) solvent as a substance that dissolves a solute (b) solute as a substance that is dissolved in a solvent (c) solution as a mixture of one or more solutes dissolved in a solvent (d) saturated solution as a solution containing the maximum concentration of a solute dissolved in the solvent at a specified temperature (e) residue as a substance that remains after evaporation, distillation, filtration or any similar process (f) filtrate as a liquid or solution that has passed through a filter",0],["12.4.1","Describe and explain methods of separation and purification using: (a) a suitable solvent (b) filtration (c) crystallisation (d) simple distillation (e) fractional distillation",0],["12.4.2","Suggest suitable separation and purification techniques, given information about the substances involved",0],["12.4.3","Identify substances and assess their purity using melting point and boiling point information",0]],"12.2":[["12.2.2","Describe how to identify the end-point of a titration using an indicator",0]],"12.3":[["12.3.1","Describe how paper chromatography is used to separate mixtures of soluble coloured substances, using a suitable solvent",0],["12.3.2","Interpret simple chromatograms to identify: (a) unknown substances by comparison with known substances (b) pure and impure substances",0],["12.3.3","Describe how paper chromatography is used to separate mixtures of soluble colourless substances, using a suitable solvent and a locating agent Knowledge of specific locating agents is not required",1],["12.3.4","State and use the equation for R : f distance travelled by substance R = f distance travelled by solvent",1]],"12.5":[["12.5.1","Describe tests to identify the anions: (a) carbonate, CO₃²⁻, by reaction with dilute acid and then testing for carbon dioxide gas (b) chloride, Cl⁻, bromide, Br⁻, and iodide, I⁻, by acidifying with dilute nitric acid then adding aqueous silver nitrate (c) nitrate, NO₃⁻, reduction with aluminium foil and aqueous sodium hydroxide and then testing for ammonia gas (d) sulfate, SO₄²⁻, by acidifying with dilute nitric acid and then adding aqueous barium nitrate (e) sulfite, SO₃²⁻, by reaction with acidified aqueous potassium manganate(VII)",0]],"12.6":[["12.5.2","Describe tests using aqueous sodium hydroxide and aqueous ammonia to identify the aqueous cations: (a) aluminium, Al³⁺ (b) ammonium, NH₄⁺ (c) calcium, Ca²⁺ (d) chromium(III), Cr³⁺ (e) copper(II), Cu²⁺ (f) iron(II), Fe²⁺ (g) iron(III), Fe³⁺ (h) zinc, Zn²⁺",0],["12.5.4","Describe the use of a flame test to identify the cations: (a) lithium, Li⁺ (b) sodium, Na⁺ (c) potassium, K⁺ (d) calcium, Ca²⁺ (e) barium, Ba²⁺ (f) copper(II), Cu²⁺",0]],"12.7":[["12.5.3","Describe tests to identify the gases: (a) ammonia, NH₃, using damp red litmus paper (b) carbon dioxide, CO₂, using limewater (c) chlorine, Cl₂, using damp litmus paper (d) hydrogen, H₂, using a lighted splint (e) oxygen, O₂, using a glowing splint (f) sulfur dioxide, SO₂, using acidified aqueous potassium manganate(VII)",0]]},"bio":{"1.1":[["1.1.1","Describe the characteristics of living organisms by describing: (a) movement as an action by an organism or part of an organism causing a change of position or place (b) respiration as the chemical reactions in cells that break down nutrient molecules and release energy for metabolism (c) sensitivity as the ability to detect and respond to changes in the internal or external environment (d) growth as a permanent increase in size and dry mass (e) reproduction as the processes that make more of the same kind of organism (f) excretion as the removal of the waste products of metabolism and substances in excess of requirements (g) nutrition as the taking in of materials for energy, growth and development",0]],"1.2":[["1.2.1","State that organisms can be classified into groups by the features that they share",0],["1.2.2","Describe a species as a group of organisms that can reproduce to produce fertile offspring",0],["1.2.3","Describe the binomial system of naming species as an internationally agreed system in which the scientific name of an organism is made up of two parts showing the genus and species",0],["1.2.4","Construct and use dichotomous keys based on identifiable features",0],["1.2.5","Explain that classification systems aim to reflect evolutionary relationships",1],["1.2.6","Explain that the sequences of bases in DNA are used as a means of classification",1],["1.2.7","Explain that groups of organisms which share a more recent ancestor (are more closely related) have base sequences in DNA that are more similar than those that share only a distant ancestor",1],["1.3.3","Classify organisms using the features identified in 1.3.1 and 1.3.2",0],["1.3.6","Classify organisms using the features identified in 1.3.4 and 1.3.5",1]],"1.3":[["1.3.1","State the main features used to place animals and plants into the appropriate kingdoms",0],["1.3.2","State the main features used to place organisms into groups within the animal kingdom, limited to: (a) the main groups of vertebrates: mammals, birds, reptiles, amphibians, fish (b) the main groups of arthropods: myriapods, insects, arachnids, crustaceans",0],["1.3.4","State the main features used to place all organisms into one of the five kingdoms: animal, plant, fungus, prokaryote, protoctist",1],["1.3.5","State the main features used to place organisms into groups within the plant kingdom, limited to ferns and flowering plants (dicotyledons and monocotyledons)",1],["1.3.7","State the features of viruses, limited to a protein coat and genetic material",1]],"2.1":[["2.1.1","Describe and compare the structure of a plant cell with an animal cell, limited to: cell wall, cell membrane, nucleus, cytoplasm, chloroplasts, ribosomes, mitochondria, vacuoles",0],["2.1.2","Describe the structure of a bacterial cell, limited to: cell wall, cell membrane, cytoplasm, ribosomes, circular DNA, plasmids",0],["2.1.4","Describe the functions of the structures listed in 2.1.1 and 2.1.2 in plant, animal and bacterial cells",0],["2.1.5","State that new cells are produced by division of existing cells",0]],"2.2":[["2.1.3","Identify the cell structures listed in 2.1.1 and 2.1.2 in diagrams and images of plant, animal and bacterial cells",0],["2.1.6","State that specialised cells have specific functions, limited to: (a) ciliated cells – movement of mucus in the trachea and bronchi (b) root hair cells – absorption (c) palisade mesophyll cells – photosynthesis (d) neurones – conduction of electrical impulses (e) red blood cells – transport of oxygen (f) sperm and egg cells (gametes) – reproduction",0],["2.1.7","Describe the meaning of the terms: cell, tissue, organ, organ system and organism as illustrated by examples given in the syllabus",0]],"2.3":[["2.2.1","State and use the formula: magnification = image size ÷ actual size",0],["2.2.2","Calculate magnification and size of biological specimens using millimetres as units",0],["2.2.3","Convert measurements between millimetres (mm) and micrometres (μm)",1]],"3.1":[["3.1.1","Describe diffusion as the net movement of particles from a region of their higher concentration to a region of their lower concentration (i.e. down a concentration gradient), as a result of their random movement",0],["3.1.2","State that the energy for diffusion comes from the kinetic energy of random movement of molecules and ions",0],["3.1.3","State that some substances move into and out of cells by diffusion through the cell membrane",0],["3.1.4","Describe the importance of diffusion of gases and solutes in living organisms",0],["3.1.5","Investigate the factors that influence diffusion, limited to: surface area, temperature, concentration gradient and distance",0],["3.2.2","State that water diffuses through partially permeable membranes by osmosis",0],["3.3.1","Describe active transport as the movement of particles through a cell membrane from a region of lower concentration to a region of higher concentration (i.e. against a concentration gradient), using energy from respiration",0]],"3.2":[["3.2.1","Describe the role of water as a solvent in organisms with reference to digestion, excretion and transport",0],["3.2.3","State that water moves into and out of cells by osmosis through the cell membrane",0],["3.2.4","Investigate osmosis using materials such as dialysis tubing",0],["3.2.5","Investigate and describe the effects on plant tissues of immersing them in solutions of different concentrations",0],["3.2.6","State that plants are supported by the pressure of water inside the cells pressing outwards on the cell wall",0],["3.2.7","Describe osmosis as the net movement of water molecules from a region of higher water potential (dilute solution) to a region of lower water potential (concentrated solution), through a partially permeable membrane",1],["3.2.8","Explain the effects on plant cells of immersing them in solutions of different concentrations by using the terms: turgid, turgor pressure, plasmolysis, flaccid",1],["3.2.9","Explain the importance of water potential and osmosis in the uptake and loss of water by organisms",1]],"3.3":[["3.3.2","Explain the importance of active transport as a process for movement of molecules or ions across membranes, including ion uptake by root hairs",1],["3.3.3","State that protein carriers move molecules or ions across a membrane during active transport",1]],"4.1":[["4.1.1","List the chemical elements that make up: carbohydrates, fats and proteins",0],["4.1.2","State that large molecules are made from smaller molecules, limited to: (a) starch, glycogen and cellulose from glucose (b) proteins from amino acids (c) fats and oils from fatty acids and glycerol",0],["4.1.3","Describe the use of: (a) iodine solution test for starch (b) Benedict’s solution test for reducing sugars (c) biuret test for proteins (d) ethanol emulsion test for fats and oils (e) DCPIP test for vitamin C",0]],"4.2":[["4.1.4","Describe the structure of a DNA molecule: (a) two strands coiled together to form a double helix (b) each strand contains chemicals called bases (c) bonds between pairs of bases hold the strands together (d) the bases always pair up in the same way: A with T, and C with G (full names are not required)",1]],"5.1":[["5.1.1","Describe a catalyst as a substance that increases the rate of a chemical reaction and is not changed by the reaction",0],["5.1.2","Describe enzymes as proteins that are involved in all metabolic reactions, where they function as biological catalysts",0],["5.1.3","Describe why enzymes are important in all living organisms in terms of a reaction rate necessary to sustain life",0],["5.1.4","Describe enzyme action with reference to the shape of the active site of an enzyme being complementary to its substrate and the formation of products",0],["5.1.6","Explain enzyme action with reference to: active site, enzyme-substrate complex, substrate and product",1],["5.1.7","Explain the specificity of enzymes in terms of the complementary shape and fit of the active site with the substrate",1]],"5.2":[["5.1.5","Investigate and describe the effect of changes in temperature and pH on enzyme activity with reference to optimum temperature and denaturation",0],["5.1.8","Explain the effect of changes in temperature on enzyme activity in terms of kinetic energy, shape and fit, frequency of effective collisions and denaturation",1],["5.1.9","Explain the effect of changes in pH on enzyme activity in terms of shape and fit and denaturation",1]],"6.1":[["6.1.1","Describe photosynthesis as the process by which plants synthesise carbohydrates from raw materials using energy from light",0],["6.1.2","State the word equation for photosynthesis as: carbon dioxide + water → glucose + oxygen in the presence of light and chlorophyll",0],["6.1.3","State that chlorophyll is a green pigment that is found in chloroplasts",0],["6.1.4","State that chlorophyll transfers energy from light into energy in chemicals, for the synthesis of carbohydrates",0],["6.1.5","Outline the subsequent use and storage of the carbohydrates made in photosynthesis, limited to: (a) starch as an energy store (b) cellulose to build cell walls (c) glucose used in respiration to provide energy (d) sucrose for transport in the phloem (e) nectar to attract insects for pollination",0],["6.1.6","Explain the importance of: (a) nitrate ions for making amino acids (b) magnesium ions for making chlorophyll",0],["6.1.7","Investigate the need for chlorophyll, light and carbon dioxide for photosynthesis, using appropriate controls",0],["6.1.8","Investigate and describe the effects of varying light intensity, carbon dioxide concentration and temperature on the rate of photosynthesis",0],["6.1.10","State the balanced chemical equation for photosynthesis as: 6CO~2~ + 6H~2~O → C~6~H~12~O~6~ + 6O~2~",1]],"6.2":[["6.1.9","Investigate and describe the effect of light and dark conditions on gas exchange in an aquatic plant using hydrogencarbonate indicator solution",0],["6.1.11","Identify and explain the limiting factors of photosynthesis in different environmental conditions",1]],"6.3":[["6.2.1","State that most leaves have a large surface area and are thin, and explain how these features are adaptations for photosynthesis",0],["6.2.2","Identify in diagrams and images the following structures in the leaf of a dicotyledonous plant: chloroplasts, cuticle, guard cells and stomata, upper and lower epidermis, palisade mesophyll, spongy mesophyll, air spaces, vascular bundles, xylem and phloem",0],["6.2.3","Explain how the structures listed in 6.2.2 adapt leaves for photosynthesis",0]],"7.1":[["7.1.1","Describe what is meant by a balanced diet",0],["7.1.2","State the principal dietary sources and describe the importance of: (a) carbohydrates (b) fats and oils (c) proteins (d) vitamins, limited to C and D (e) mineral ions, limited to calcium and iron (f) fibre (roughage) (g) water",0],["7.1.3","State the causes of scurvy and rickets",0]],"7.2":[["7.2.1","Identify in diagrams and images the main organs of the digestive system, limited to: (a) alimentary canal: mouth, oesophagus, stomach, small intestine (duodenum and ileum) and large intestine (colon, rectum, anus) (b) associated organs: salivary glands, pancreas, liver and gall bladder",0],["7.2.2","Describe the functions of the organs of the digestive system listed in 7.2.1, in relation to: (a) ingestion – the taking of substances, e.g. food and drink, into the body (b) digestion – the breakdown of food (c) absorption – the movement of nutrients from the intestines into the blood (d) assimilation – uptake and use of nutrients by cells (e) egestion – the removal of undigested food from the body as faeces",0],["7.3.1","Describe physical digestion as the breakdown of food into smaller pieces without chemical change to the food molecules",0],["7.3.2","State that physical digestion increases the surface area of food for the action of enzymes in chemical digestion",0],["7.3.3","Identify in diagrams and images the types of human teeth: incisors, canines, premolars and molars",0],["7.3.4","Describe the structure of human teeth, limited to: enamel, dentine, pulp, nerves, blood vessels and cement, and understand that teeth are embedded in bone and the gums",0],["7.3.5","Describe the functions of the types of human teeth in physical digestion of food",0],["7.3.6","Describe the function of the stomach in physical digestion",0],["7.4.1","Describe chemical digestion as the breakdown of large insoluble molecules into small soluble molecules",0]],"7.3":[["7.3.7","Outline the role of bile in emulsifying fats and oils to increase the surface area for chemical digestion",1],["7.4.2","State the role of chemical digestion in producing small soluble molecules that can be absorbed",0],["7.4.3","Describe the functions of enzymes as follows: (a) amylase breaks down starch to simple reducing sugars (b) proteases break down protein to amino acids (c) lipase breaks down fats and oils to fatty acids and glycerol",0],["7.4.4","State where, in the digestive system, amylase, protease and lipase are secreted and where they act",0],["7.4.5","Describe the functions of hydrochloric acid in gastric juice, limited to killing harmful microorganisms in food and providing an acidic pH for optimum enzyme activity",0],["7.4.6","Describe the digestion of starch in the digestive system: (a) amylase breaks down starch to maltose (b) maltase breaks down maltose to glucose on the membranes of the epithelium lining the small intestine",1],["7.4.7","Describe the digestion of protein by proteases in the digestive system: (a) pepsin breaks down protein in the acidic conditions of the stomach (b) trypsin breaks down protein in the alkaline conditions of the small intestine",1],["7.4.8","Explain that bile is an alkaline mixture that neutralises the acidic mixture of food and gastric juices entering the duodenum from the stomach, to provide a suitable pH for enzyme action",1],["7.5.1","State that the small intestine is the region where nutrients are absorbed",0],["7.5.2","State that most water is absorbed from the small intestine but that some is also absorbed from the colon",0],["7.5.3","Explain the significance of villi and microvilli in increasing the internal surface area of the small intestine",1],["7.5.4","Describe the structure of a villus",1],["7.5.5","Describe the roles of capillaries and lacteals in villi",1]],"8.1":[["8.1.1","State the functions of xylem and phloem: (a) xylem – transport of water and mineral ions, and support (b) phloem – transport of sucrose and amino acids",0],["8.1.2","Identify in diagrams and images the position of xylem and phloem as seen in sections of roots, stems and leaves of non-woody dicotyledonous plants",0],["8.1.3","Relate the structure of xylem vessels to their function, limited to: (a) thick walls with lignin (details of lignification are not required) (b) no cell contents (c) cells joined end to end with no cross walls to form a long continuous tube",1],["8.2.1","Identify in diagrams and images root hair cells and state their functions",0],["8.2.2","State that the large surface area of root hairs increases the uptake of water and mineral ions",0],["8.2.3","Outline the pathway taken by water through the root, stem and leaf as: root hair cells, root cortex cells, xylem, mesophyll cells",0],["8.2.4","Investigate, using a suitable stain, the pathway of water through the above-ground parts of a plant",0],["8.3.1","Describe transpiration as the loss of water vapour from leaves",0]],"8.2":[["8.3.2","State that water evaporates from the surfaces of the mesophyll cells into the air spaces and then diffuses out of the leaves through the stomata as water vapour",0],["8.3.3","Investigate and describe the effects of variation of temperature and wind speed on transpiration rate",0],["8.3.4","Explain how water vapour loss is related to: the large internal surface area provided by the interconnecting air spaces between mesophyll cells and the size and number of stomata",1],["8.3.5","Explain the mechanism by which water moves upwards in the xylem in terms of a transpiration pull that draws up a column of water molecules, held together by forces of attraction between water molecules",1],["8.3.6","Explain the effects on the rate of transpiration of varying the following factors: temperature, wind speed and humidity",1],["8.3.7","Explain how and why wilting occurs",1]],"8.3":[["8.4.1","Describe translocation as the movement of sucrose and amino acids in phloem from sources to sinks",1],["8.4.2","Describe: (a) sources as the parts of plants that release sucrose or amino acids (b) sinks as the parts of plants that use or store sucrose or amino acids",1],["8.4.3","Explain why some parts of a plant may act as a source and a sink at different times",1]],"9.1":[["9.1.1","Describe the circulatory system as a system of blood vessels with a pump and valves to ensure one-way flow of blood",0],["9.1.2","Describe the single circulation of a fish",1],["9.1.3","Describe the double circulation of a mammal",1],["9.1.4","Explain the advantages of a double circulation",1],["9.2.1","Identify in diagrams and images the structures of the mammalian heart, limited to: muscular wall, septum, left and right ventricles, left and right atria, one-way valves and coronary arteries",0],["9.2.2","State that blood is pumped away from the heart in arteries and returns to the heart in veins",0],["9.2.3","State that the activity of the heart may be monitored by: ECG, pulse rate and listening to sounds of valves closing",0],["9.2.4","Investigate and describe the effect of physical activity on the heart rate",0],["9.2.5","Describe coronary heart disease in terms of the blockage of coronary arteries and state the possible risk factors including: diet, lack of exercise, stress, smoking, genetic predisposition, age and sex",0],["9.2.6","Discuss the roles of diet and exercise in reducing the risk of coronary heart disease",0],["9.2.7","Identify in diagrams and images the atrioventricular and semilunar valves in the mammalian heart",1],["9.2.8","Explain the relative thickness of: (a) the muscle walls of the left and right ventricles (b) the muscle walls of the atria compared to those of the ventricles",1],["9.2.9","Explain the importance of the septum in separating oxygenated and deoxygenated blood",1],["9.2.10","Describe the functioning of the heart in terms of the contraction of muscles of the atria and ventricles and the action of the valves",1],["9.2.11","Explain the effect of physical activity on the heart rate",1],["9.3.2","State the functions of capillaries",0]],"9.2":[["9.3.1","Describe the structure of arteries, veins and capillaries, limited to: relative thickness of wall, diameter of the lumen and the presence of valves in veins",0],["9.3.3","Identify in diagrams and images the main blood vessels to and from the: (a) heart, limited to: vena cava, aorta, pulmonary artery and pulmonary vein (b) lungs, limited to: pulmonary artery and pulmonary vein (c) kidney, limited to: renal artery and renal vein",0],["9.3.4","Explain how the structure of arteries and veins is related to the pressure of the blood that they transport",1],["9.3.5","Explain how the structure of capillaries is related to their functions",1],["9.3.6","Identify, in diagrams and images, the main blood vessels to and from the liver as: hepatic artery, hepatic veins and hepatic portal vein",1]],"9.3":[["9.4.1","List the components of blood as: red blood cells, white blood cells, platelets and plasma",0],["9.4.2","Identify red and white blood cells in photomicrographs and diagrams",0],["9.4.3","State the functions of the following components of blood: (a) red blood cells in transporting oxygen, including the role of haemoglobin (b) white blood cells in phagocytosis and antibody production (c) platelets in clotting (details are not required) (d) plasma in the transport of blood cells, ions, nutrients, urea, hormones and carbon dioxide",0],["9.4.4","State the roles of blood clotting as preventing blood loss and the entry of pathogens",0],["9.4.5","Identify lymphocytes and phagocytes in photomicrographs and diagrams",1],["9.4.6","State the functions of: (a) lymphocytes – antibody production (b) phagocytes – engulfing pathogens by phagocytosis",1],["9.4.7","Describe the process of clotting as the conversion of fibrinogen to fibrin to form a mesh",1]],"10.1":[["10.1.1","Describe a pathogen as a disease-causing organism",0],["10.1.2","Describe a transmissible disease as a disease in which the pathogen can be passed from one host to another",0],["10.1.3","State that a pathogen is transmitted: (a) by direct contact, including through blood and other body fluids (b) indirectly, including from contaminated surfaces, food, animals and air",0],["10.1.4","Describe the body defences, limited to: skin, hairs in the nose, mucus, stomach acid and white blood cells",0],["10.1.5","Explain the importance of the following in controlling the spread of disease: (a) a clean water supply (b) hygienic food preparation (c) good personal hygiene (d) waste disposal (e) sewage treatment (details of the stages of sewage treatment are not required)",0],["10.1.12","Explain the role of vaccination in controlling the spread of diseases",1],["10.1.16","Describe cholera as a disease caused by a bacterium which is transmitted in contaminated water",1],["10.1.17","Explain that the cholera bacterium produces a toxin that causes secretion of chloride ions into the small intestine, causing osmotic movement of water into the gut, causing diarrhoea, dehydration and loss of ions from the blood",1]],"10.2":[["10.1.6","Describe active immunity as defence against a pathogen by antibody production in the body",1],["10.1.7","State that each pathogen has its own antigens, which have specific shapes",1],["10.1.8","Describe antibodies as proteins that bind to antigens leading to direct destruction of pathogens or marking of pathogens for destruction by phagocytes",1],["10.1.9","State that specific antibodies have complementary shapes which fit specific antigens",1],["10.1.10","Explain that active immunity is gained after an infection by a pathogen or by vaccination",1],["10.1.11","Outline the process of vaccination: (a) weakened pathogens or their antigens are put into the body (b) the antigens stimulate an immune response by lymphocytes which produce antibodies (c) memory cells are produced that give long-term immunity",1],["10.1.13","Explain that passive immunity is a short-term defence against a pathogen by antibodies acquired from another individual, including across the placenta and in breast milk",1],["10.1.14","Explain the importance of breast-feeding for the development of passive immunity in infants",1],["10.1.15","State that memory cells are not produced in passive immunity",1]],"11.1":[["11.1.1","Describe the features of gas exchange surfaces in humans, limited to: large surface area, thin surface, good blood supply and good ventilation with air",0],["11.1.2","Identify in diagrams and images the following parts of the breathing system: lungs, diaphragm, ribs, intercostal muscles, larynx, trachea, bronchi, bronchioles, alveoli and associated capillaries",0],["11.1.6","Identify in diagrams and images the internal and external intercostal muscles",1],["11.1.7","State the function of cartilage in the trachea",1],["11.1.11","Explain the role of goblet cells, mucus and ciliated cells in protecting the breathing system from pathogens and particles",1]],"11.2":[["11.1.3","Investigate the differences in composition between inspired and expired air using limewater as a test for carbon dioxide",0],["11.1.4","Describe the differences in composition between inspired and expired air, limited to: oxygen, carbon dioxide and water vapour",0],["11.1.5","Investigate and describe the effects of physical activity on the rate and depth of breathing",0],["11.1.8","Explain the role of the ribs, the internal and external intercostal muscles and the diaphragm in producing volume and pressure changes in the thorax leading to the ventilation of the lungs",1],["11.1.9","Explain the differences in composition between inspired and expired air",1],["11.1.10","Explain the link between physical activity and the rate and depth of breathing in terms of: an increased carbon dioxide concentration in the blood, which is detected by the brain, leading to an increased rate and greater depth of breathing",1]],"12.1":[["12.1.1","State the uses of energy in living organisms, including: muscle contraction, protein synthesis, cell division, active transport, growth, the passage of nerve impulses and the maintenance of a constant body temperature",0],["12.1.2","Investigate and describe the effect of temperature on respiration in yeast",0],["12.2.1","Describe aerobic respiration as the chemical reactions in cells that use oxygen to break down nutrient molecules to release energy",0],["12.2.2","State the word equation for aerobic respiration as: glucose + oxygen → carbon dioxide + water",0],["12.2.3","State the balanced chemical equation for aerobic respiration as: C~6~H~12~O~6~ + 6O~2~ → 6CO~2~ + 6H~2~O",1]],"12.2":[["12.3.1","Describe anaerobic respiration as the chemical reactions in cells that break down nutrient molecules to release energy without using oxygen",0],["12.3.2","State that anaerobic respiration releases much less energy per glucose molecule than aerobic respiration",0],["12.3.3","State the word equation for anaerobic respiration in yeast as: glucose → alcohol + carbon dioxide",0],["12.3.4","State the word equation for anaerobic respiration in muscles during vigorous exercise as: glucose → lactic acid",0],["12.3.5","State the balanced chemical equation for anaerobic respiration in yeast as: C~6~H~12~O~6~ → 2C~2~H~5~OH + 2CO~2~",1],["12.3.6","State that lactic acid builds up in muscles and blood during vigorous exercise causing an oxygen debt",1],["12.3.7","Outline how the oxygen debt is removed after exercise, limited to: (a) continuation of fast heart rate to transport lactic acid in the blood from the muscles to the liver (b) continuation of deeper and faster breathing to supply oxygen for aerobic respiration of lactic acid (c) aerobic respiration of lactic acid in the liver",1]],"13.1":[["13.1.1","State that carbon dioxide is excreted through the lungs",0],["13.1.3","Identify in diagrams and images the kidneys, ureters, bladder and urethra",0],["13.1.6","Describe the role of the liver in the assimilation of amino acids by converting them to proteins",1],["13.1.7","State that urea is formed in the liver from excess amino acids",1],["13.1.8","Describe deamination as the removal of the nitrogen-containing part of amino acids to form urea",1],["13.1.9","Explain the importance of excretion, limited to toxicity of urea",1]],"13.2":[["13.1.2","State that the kidneys excrete urea and excess water and ions",0],["13.1.4","Identify in diagrams and images the structure of the kidney, limited to the cortex and medulla",1],["13.1.5","Outline the structure and function of a nephron and its associated blood vessels, limited to: (a) the role of the glomerulus in the filtration from the blood of water, glucose, urea and ions (b) the role of the nephron in the reabsorption of all of the glucose, some of the ions and most of the water back into the blood (c) the formation of urine containing urea, excess water and excess ions (details of these processes are not required)",1]],"14.1":[["14.1.1","State that electrical impulses travel along neurones",0],["14.1.2","Describe the mammalian nervous system in terms of: (a) the central nervous system (CNS) consisting of the brain and the spinal cord (b) the peripheral nervous system (PNS) consisting of the nerves outside of the brain and spinal cord",0],["14.1.4","Identify in diagrams and images sensory, relay and motor neurones",0],["14.1.5","Describe a simple reflex arc in terms of: receptor, sensory neurone, relay neurone, motor neurone and effector",0],["14.1.6","Describe a reflex action as a means of automatically and rapidly integrating and coordinating stimuli with the responses of effectors (muscles and glands)",0],["14.1.7","Describe a synapse as a junction between two neurones",0],["14.1.8","Describe the structure of a synapse, including the presence of vesicles containing neurotransmitter molecules, the synaptic gap and receptor proteins",1],["14.1.9","Describe the events at a synapse as: (a) an impulse stimulates the release of neurotransmitter molecules from vesicles into the synaptic gap (b) the neurotransmitter molecules diffuse across the gap (c) neurotransmitter molecules bind with receptor proteins on the next neurone (d) an impulse is then stimulated in the next neurone",1],["14.1.10","State that synapses ensure that impulses travel in one direction only",1]],"14.5":[["14.1.3","Describe the role of the nervous system as coordination and regulation of body functions",0],["14.4.6","Identify in diagrams and images of the skin: hairs, hair erector muscles, sweat glands, receptors, sensory neurones, blood vessels and fatty tissue",1],["14.4.7","Describe the maintenance of a constant internal body temperature in mammals in terms of: insulation, sweating, shivering and the role of the brain",1],["14.4.8","Describe the maintenance of a constant internal body temperature in mammals in terms of vasodilation and vasoconstriction of arterioles supplying skin surface capillaries",1]],"14.2":[["14.2.1","Describe sense organs as groups of receptor cells responding to specific stimuli: light, sound, touch, temperature and chemicals",0],["14.2.2","Identify in diagrams and images the structures of the eye, limited to: cornea, iris, pupil, lens, retina, optic nerve and blind spot",0],["14.2.3","Describe the function of each part of the eye, limited to: (a) cornea – refracts light (b) iris – controls how much light enters the pupil (c) lens – focuses light on to the retina (d) retina – contains light receptors, some sensitive to light of different colours (e) optic nerve – carries impulses to the brain",0],["14.2.4","Explain the pupil reflex, limited to changes in light intensity and pupil diameter",0],["14.2.5","Explain the pupil reflex in terms of the antagonistic action of circular and radial muscles in the iris",1],["14.2.6","Explain accommodation to view near and distant objects in terms of the contraction and relaxation of the ciliary muscles, tension in the suspensory ligaments, shape of the lens and refraction of light",1],["14.2.7","Describe the distribution of rods and cones in the retina of a human",1],["14.2.8","Outline the function of rods and cones, limited to: (a) greater sensitivity of rods for night vision (b) three different kinds of cones, absorbing light of different colours, for colour vision",1],["14.2.9","Identify in diagrams and images the position of the fovea and state its function",1]],"14.3":[["14.3.1","Describe a hormone as a chemical substance, produced by a gland and carried by the blood, which alters the activity of one or more specific target organs",0],["14.3.2","Identify in diagrams and images specific endocrine glands and state the hormones they secrete, limited to: (a) adrenal glands and adrenaline (b) pancreas and insulin (c) testes and testosterone (d) ovaries and oestrogen",0],["14.3.3","Describe adrenaline as the hormone secreted in ‘fight or flight’ situations and its effects, limited to: (a) increased breathing rate (b) increased heart rate (c) increased pupil diameter",0],["14.3.4","Compare nervous and hormonal control, limited to speed of action and duration of effect",0],["14.3.6","Describe the role of adrenaline in the control of metabolic activity, limited to: (a) increasing the blood glucose concentration (b) increasing heart rate",1],["14.4.4","Describe the control of blood glucose concentration by the liver and the roles of insulin and glucagon",1]],"14.4":[["14.3.5","State that glucagon is secreted by the pancreas",1],["14.4.1","Describe homeostasis as the maintenance of a constant internal environment",0],["14.4.2","State that insulin decreases blood glucose concentration",0],["14.4.3","Explain the concept of homeostatic control by negative feedback with reference to a set point",1],["14.4.5","Outline the treatment of Type 1 diabetes",1]],"14.6":[["14.5.1","Describe gravitropism as a response in which parts of a plant grow towards or away from gravity",0],["14.5.2","Describe phototropism as a response in which parts of a plant grow towards or away from the direction of the light source",0],["14.5.3","Investigate and describe gravitropism and phototropism in shoots and roots",0],["14.5.4","Explain phototropism and gravitropism of a shoot as examples of the chemical control of plant growth",1],["14.5.5","Explain the role of auxin in controlling shoot growth, limited to: (a) auxin is made in the shoot tip (b) auxin diffuses through the plant from the shoot tip (c) auxin is unequally distributed in response to light and gravity (d) auxin stimulates cell elongation",1]],"15.1":[["15.1.1","Describe a drug as any substance taken into the body that modifies or affects chemical reactions in the body",0],["15.1.2","Describe the use of antibiotics for the treatment of bacterial infections",0],["15.1.3","State that some bacteria are resistant to antibiotics which reduces the effectiveness of antibiotics",0],["15.1.4","State that antibiotics kill bacteria but do not affect viruses",0],["15.1.5","Explain how using antibiotics only when essential can limit the development of resistant bacteria such as MRSA",1]],"16.1":[["16.1.1","Describe asexual reproduction as a process resulting in the production of genetically identical offspring from one parent",0],["16.1.2","Identify examples of asexual reproduction in diagrams, images and information provided",0],["16.1.3","Discuss the advantages and disadvantages of asexual reproduction: (a) to a population of a species in the wild (b) to crop production",1],["16.2.1","Describe sexual reproduction as a process involving the fusion of the nuclei of two gametes to form a zygote and the production of offspring that are genetically different from each other",0],["16.2.2","Describe fertilisation as the fusion of the nuclei of gametes",0],["16.2.3","State that nuclei of gametes are haploid and that the nucleus of a zygote is diploid",1],["16.2.4","Discuss the advantages and disadvantages of sexual reproduction: (a) to a population of a species in the wild (b) to crop production",1],["16.4.3","Describe fertilisation as the fusion of the nuclei from a male gamete (sperm) and a female gamete (egg cell)",0]],"16.2":[["16.3.1","Identify in diagrams and images and draw the following parts of an insect-pollinated flower: sepals, petals, stamens, filaments, anthers, carpels, style, stigma, ovary and ovules",0],["16.3.2","State the functions of the structures listed in 16.3.1",0],["16.3.3","Identify in diagrams and images and describe the anthers and stigmas of a wind-pollinated flower",0],["16.3.4","Distinguish between the pollen grains of insect-pollinated and wind-pollinated flowers",0],["16.3.5","Describe pollination as the transfer of pollen grains from an anther to a stigma",0],["16.3.6","State that fertilisation occurs when a pollen nucleus fuses with a nucleus in an ovule",0],["16.3.7","Describe the structural adaptations of insect-pollinated and wind-pollinated flowers",0],["16.3.8","Investigate and describe the environmental conditions that affect germination of seeds, limited to the requirement for: water, oxygen and a suitable temperature",0],["16.3.9","Describe self-pollination as the transfer of pollen grains from the anther of a flower to the stigma of the same flower or a different flower on the same plant",1],["16.3.10","Describe cross-pollination as the transfer of pollen grains from the anther of a flower to the stigma of a flower on a different plant of the same species",1],["16.3.11","Discuss the potential effects of self-pollination and cross-pollination on a population, in terms of variation, capacity to respond to changes in the environment and reliance on pollinators",1],["16.3.12","Describe the growth of the pollen tube and its entry into the ovule followed by fertilisation (details of production of endosperm and development are not required)",1]],"16.3":[["16.4.1","Identify on diagrams and state the functions of the following parts of the male reproductive system: testes, scrotum, sperm ducts, prostate gland, urethra and penis",0],["16.4.2","Identify on diagrams and state the functions of the following parts of the female reproductive system: ovaries, oviducts, uterus, cervix and vagina",0],["16.4.4","Explain the adaptive features of sperm, limited to: flagellum, mitochondria and enzymes in the acrosome",0],["16.4.5","Explain the adaptive features of egg cells, limited to: energy stores and the jelly coat that changes at fertilisation",0],["16.4.6","Compare male and female gametes in terms of: size, structure, motility and numbers",0],["16.4.7","State that in early development, the zygote forms an embryo which is a ball of cells that implants into the lining of the uterus",0],["16.4.8","Identify on diagrams and state the functions of the following in the development of the fetus: umbilical cord, placenta, amniotic sac and amniotic fluid",0],["16.4.9","Describe the function of the placenta and umbilical cord in relation to the exchange of dissolved nutrients, gases and excretory products between the blood of the mother and the blood of the fetus",1],["16.4.10","State that some pathogens and toxins can pass across the placenta and affect the fetus",1]],"16.4":[["16.5.1","Describe the roles of testosterone and oestrogen in the development and regulation of secondary sexual characteristics during puberty",0],["16.5.2","Describe the menstrual cycle in terms of changes in the ovaries and in the lining of the uterus",0],["16.5.3","Describe the sites of production of oestrogen and progesterone in the menstrual cycle and in pregnancy",1],["16.5.4","Explain the role of hormones in controlling the menstrual cycle and pregnancy, limited to FSH, LH, progesterone and oestrogen",1],["16.6.1","Describe a sexually transmitted infection (STI) as an infection that is transmitted through sexual contact",0],["16.6.2","State that human immunodeficiency virus (HIV) is a pathogen that causes an STI",0],["16.6.3","State that HIV infection may lead to AIDS",0],["16.6.4","Describe the methods of transmission of HIV",0],["16.6.5","Explain how the spread of STIs is controlled",0]],"17.1":[["17.1.1","State that chromosomes are made of DNA, which contains genetic information in the form of genes",0],["17.1.2","Define a gene as a length of DNA that codes for a protein",0],["17.1.3","Define an allele as an alternative form of a gene",0],["17.1.4","Describe the inheritance of sex in humans with reference to X and Y chromosomes",0],["17.1.5","State that the sequence of bases in a gene determines the sequence of amino acids used to make a specific protein (knowledge of the details of nucleotide structure is not required)",1],["17.1.6","Explain that different sequences of amino acids give different shapes to protein molecules",1],["17.1.7","Explain that DNA controls cell function by controlling the production of proteins, including enzymes, membrane carriers and receptors for neurotransmitters",1],["17.1.8","Explain how a protein is made, limited to: the gene coding for the protein remains in the nucleus; messenger RNA (mRNA) is a copy of a gene; mRNA molecules are made in the nucleus and move to the cytoplasm; the mRNA passes through ribosomes; the ribosome assembles amino acids into protein molecules; the specific sequence of amino acids is determined by the sequence of bases in the mRNA (knowledge of the details of transcription or translation is not required)",1],["17.1.9","Explain that most body cells in an organism contain the same genes, but many genes in a particular cell are not expressed because the cell only makes the specific proteins it needs",1],["17.1.10","Describe a haploid nucleus as a nucleus containing a single set of chromosomes",1],["17.1.11","Describe a diploid nucleus as a nucleus containing two sets of chromosomes",1],["17.4.1","Describe inheritance as the transmission of genetic information from generation to generation",0],["17.4.16","Describe a sex-linked characteristic as a feature in which the gene responsible is located on a sex chromosome and that this makes the characteristic more common in one sex than in the other",1]],"17.2":[["17.1.12","State that in a diploid cell, there is a pair of each type of chromosome and in a human diploid cell there are 23 pairs",1],["17.2.1","Describe mitosis as nuclear division giving rise to genetically identical cells (details of the stages of mitosis are not required)",1],["17.2.2","State the role of mitosis in growth, repair of damaged tissues, replacement of cells and asexual reproduction",1],["17.2.3","State that the exact replication of chromosomes occurs before mitosis",1],["17.2.4","State that during mitosis, the copies of chromosomes separate, maintaining the chromosome number in each daughter cell",1],["17.2.5","Describe stem cells as unspecialised cells that divide by mitosis to produce daughter cells that can become specialised for specific functions",1],["17.3.1","State that meiosis is involved in the production of gametes",1],["17.3.2","Describe meiosis as a reduction division in which the chromosome number is halved from diploid to haploid resulting in genetically different cells (details of the stages of meiosis are not required)",1]],"17.3":[["17.4.2","Describe genotype as the genetic make-up of an organism and in terms of the alleles present",0],["17.4.3","Describe phenotype as the observable features of an organism",0],["17.4.4","Describe homozygous as having two identical alleles of a particular gene",0],["17.4.5","State that two identical homozygous individuals that breed together will be pure-breeding",0],["17.4.6","Describe heterozygous as having two different alleles of a particular gene",0],["17.4.7","State that a heterozygous individual will not be pure-breeding",0],["17.4.10","Interpret pedigree diagrams for the inheritance of a given characteristic",0],["17.4.11","Use genetic diagrams to predict the results of monohybrid crosses and calculate phenotypic ratios, limited to 1 : 1 and 3 : 1 ratios",0],["17.4.12","Use Punnett squares in crosses which result in more than one genotype to work out and show the possible different genotypes",0],["17.4.13","Explain how to use a test cross to identify an unknown genotype",1]],"17.4":[["17.4.8","Describe a dominant allele as an allele that is expressed if it is present in the genotype",0],["17.4.9","Describe a recessive allele as an allele that is only expressed when there is no dominant allele of the gene present in the genotype",0],["17.4.14","Describe codominance as a situation in which both alleles in heterozygous organisms contribute to the phenotype",1],["17.4.15","Explain the inheritance of ABO blood groups: phenotypes are A, B, AB and O blood groups and alleles are I^A^, I^B^ and I^o^",1],["17.4.17","Describe red-green colour blindness as an example of sex linkage",1],["17.4.18","Use genetic diagrams to predict the results of monohybrid crosses involving codominance or sex linkage and calculate phenotypic ratios",1]],"18.1":[["18.1.1","Describe variation as differences between individuals of the same species",0],["18.1.2","State that continuous variation results in a range of phenotypes between two extremes; examples include body length and body mass",0],["18.1.3","State that discontinuous variation results in a limited number of phenotypes with no intermediates; examples include ABO blood groups, seed shape in peas and seed colour in peas",0],["18.1.4","State that discontinuous variation is usually caused by genes only and continuous variation is caused by both genes and the environment",0],["18.1.5","Investigate and describe examples of continuous and discontinuous variation",0],["18.1.6","Describe mutation as genetic change",0],["18.1.7","State that mutation is the way in which new alleles are formed",0],["18.1.8","State that ionising radiation and some chemicals increase the rate of mutation",0],["18.1.9","Describe gene mutation as a random change in the base sequence of DNA",1],["18.1.10","State that mutation, meiosis, random mating and random fertilisation are sources of genetic variation in populations",1]],"18.2":[["18.2.1","Describe an adaptive feature as an inherited feature that helps an organism to survive and reproduce in its environment",0],["18.2.2","Interpret images or other information about a species to describe its adaptive features",0],["18.2.3","Explain the adaptive features of hydrophytes and xerophytes to their environments",1]],"18.3":[["18.3.1","Describe natural selection with reference to: (a) genetic variation within populations (b) production of many offspring (c) struggle for survival, including competition for resources (d) a greater chance of reproduction by individuals that are better adapted to the environment than others (e) these individuals pass on their alleles to the next generation",0],["18.3.4","Describe adaptation as the process, resulting from natural selection, by which populations become more suited to their environment over many generations",1],["18.3.5","Describe the development of strains of antibiotic resistant bacteria as an example of natural selection",1]],"18.4":[["18.3.2","Describe selective breeding with reference to: (a) selection by humans of individuals with desirable features (b) crossing these individuals to produce the next generation (c) selection of offspring showing the desirable features",0],["18.3.3","Outline how selective breeding by artificial selection is carried out over many generations to improve crop plants and domesticated animals and apply this to given contexts",0],["18.3.6","Outline the differences between natural and artificial selection",1]],"19.1":[["19.1.1","State that the Sun is the principal source of energy input to biological systems",0],["19.1.2","Describe the flow of energy through living organisms, including light energy from the Sun and chemical energy in organisms, and its eventual transfer to the environment",0],["19.2.1","Describe a food chain as showing the transfer of energy from one organism to the next, beginning with a producer",0],["19.2.2","Construct and interpret simple food chains",0],["19.2.3","Describe a food web as a network of interconnected food chains and interpret food webs",0],["19.2.4","Describe a producer as an organism that makes its own organic nutrients, usually using energy from sunlight, through photosynthesis",0],["19.2.5","Describe a consumer as an organism that gets its energy by feeding on other organisms",0],["19.2.6","State that consumers may be classed as primary, secondary, tertiary and quaternary according to their position in a food chain",0],["19.2.7","Describe a herbivore as an animal that gets its energy by eating plants",0],["19.2.8","Describe a carnivore as an animal that gets its energy by eating other animals",0],["19.2.9","Describe a decomposer as an organism that gets its energy from dead or waste organic material",0],["19.2.10","Use food chains and food webs to describe the impact humans have through overharvesting of food species and through introducing foreign species to a habitat",0],["19.2.11","Draw, describe and interpret pyramids of numbers and pyramids of biomass",0],["19.2.12","Discuss the advantages of using a pyramid of biomass rather than a pyramid of numbers to represent a food chain",0],["19.2.13","Describe a trophic level as the position of an organism in a food chain, food web or ecological pyramid",0],["19.2.14","Identify the following as the trophic levels in food webs, food chains and ecological pyramids: producers, primary consumers, secondary consumers, tertiary consumers and quaternary consumers",0],["19.2.15","Draw, describe and interpret pyramids of energy",1],["19.2.16","Discuss the advantages of using a pyramid of energy rather than pyramids of numbers or biomass to represent a food chain",1],["19.2.17","Explain why the transfer of energy from one trophic level to another is often not efficient",1],["19.2.18","Explain, in terms of energy loss, why food chains usually have fewer than five trophic levels",1],["19.2.19","Explain why it is more energy efficient for humans to eat crop plants than to eat livestock that have been fed on crop plants",1]],"19.2":[["19.3.1","Describe the carbon cycle, limited to: photosynthesis, respiration, feeding, decomposition, formation of fossil fuels and combustion",0],["19.3.2","Describe the nitrogen cycle with reference to: decomposition of plant and animal protein to ammonium ions; nitrification; nitrogen fixation by lightning and bacteria; absorption of nitrate ions by plants; production of amino acids and proteins; feeding and digestion of proteins; deamination; denitrification",1],["19.3.3","State the roles of microorganisms in the nitrogen cycle, limited to: decomposition, nitrification, nitrogen fixation and denitrification (generic names of individual bacteria, e.g. Rhizobium, are not required)",1]],"19.3":[["19.4.1","Describe a population as a group of organisms of one species, living in the same area, at the same time",0],["19.4.2","Describe a community as all of the populations of different species in an ecosystem",0],["19.4.3","Describe an ecosystem as a unit containing the community of organisms and their environment, interacting together",0],["19.4.4","Identify and state the factors affecting the rate of population growth for a population of an organism, limited to food supply, competition, predation and disease",0],["19.4.5","Identify the lag, exponential (log), stationary and death phases in the sigmoid curve of population growth for a population growing in an environment with limited resources",0],["19.4.6","Interpret graphs and diagrams of population growth",0],["19.4.7","Explain the factors that lead to each phase in the sigmoid curve of population growth, making reference, where appropriate, to the role of limiting factors",1]],"20.1":[["20.1.1","Describe how humans have increased food production, limited to: (a) agricultural machinery to use larger areas of land and improve efficiency (b) chemical fertilisers to improve yields (c) insecticides to improve quality and yield (d) herbicides to reduce competition with weeds (e) selective breeding to improve production by crop plants and livestock",0],["20.1.2","Describe the advantages and disadvantages of large-scale monocultures of crop plants",0],["20.1.3","Describe the advantages and disadvantages of intensive livestock production",0]],"20.2":[["20.2.1","Describe biodiversity as the number of different species that live in an area",0],["20.2.2","Describe the reasons for habitat destruction, including: (a) increased area for housing, crop plant production and livestock production (b) extraction of natural resources (c) freshwater and marine pollution",0],["20.2.3","State that through altering food webs and food chains, humans can have a negative impact on habitats",0],["20.2.4","Explain the undesirable effects of deforestation as an example of habitat destruction, to include: reducing biodiversity, extinction, loss of soil, flooding and increase of carbon dioxide in the atmosphere",0],["20.3.1","Describe the effects of untreated sewage and excess fertiliser on aquatic ecosystems",0],["20.3.2","Describe the effects of non-biodegradable plastics, in both aquatic and terrestrial ecosystems",0],["20.3.3","Describe the sources and effects of pollution of the air by methane and carbon dioxide, limited to: the enhanced greenhouse effect and climate change",0],["20.3.4","Explain the process of eutrophication of water, limited to: increased availability of nitrate and other ions; increased growth of producers; increased decomposition after death of producers; increased aerobic respiration by decomposers; reduction in dissolved oxygen; death of organisms requiring dissolved oxygen in water",1]],"20.3":[["20.4.1","Describe a sustainable resource as one which is produced as rapidly as it is removed from the environment so that it does not run out",0],["20.4.2","State that some resources can be conserved and managed sustainably, limited to forests and fish stocks",0],["20.4.3","Explain why organisms become endangered or extinct, including: climate change, habitat destruction, hunting, overharvesting, pollution and introduced species",0],["20.4.4","Describe how endangered species can be conserved, limited to: (a) monitoring and protecting species and habitats (b) education (c) captive breeding programmes (d) seed banks",0],["20.4.5","Explain how forests can be conserved using: education, protected areas, quotas and replanting",1],["20.4.6","Explain how fish stocks can be conserved using: education, closed seasons, protected areas, controlled net types and mesh size, quotas and monitoring",1],["20.4.7","Describe the reasons for conservation programmes, limited to: (a) maintaining or increasing biodiversity (b) reducing extinction (c) protecting vulnerable ecosystems (d) maintaining ecosystem functions, limited to nutrient cycling and resource provision, including food, drugs, fuel and genes",1],["20.4.8","Describe the use of artificial insemination (AI) and in vitro fertilisation (IVF) in captive breeding programmes",1],["20.4.9","Explain the risks to a species if its population size decreases, reducing genetic variation (knowledge of genetic drift is not required)",1]],"21.1":[["21.1.1","State that bacteria are useful in biotechnology and genetic modification due to their rapid reproduction rate and their ability to make complex molecules",0],["21.2.1","Describe the role of anaerobic respiration in yeast during the production of ethanol for biofuels",0],["21.2.2","Describe the role of anaerobic respiration in yeast during bread-making",0],["21.2.3","Describe the use of pectinase in fruit juice production",0],["21.2.4","Investigate and describe the use of biological washing powders that contain enzymes",0],["21.2.5","Explain the use of lactase to produce lactose-free milk",1]],"21.3":[["21.1.2","Discuss why bacteria are useful in biotechnology and genetic modification, limited to: (a) few ethical concerns over their manipulation and growth (b) the presence of plasmids",1],["21.3.1","Describe genetic modification as changing the genetic material of an organism by removing, changing or inserting individual genes",0],["21.3.2","Outline examples of genetic modification: (a) the insertion of human genes into bacteria to produce human proteins (b) the insertion of genes into crop plants to confer resistance to herbicides (c) the insertion of genes into crop plants to confer resistance to insect pests (d) the insertion of genes into crop plants to improve nutritional qualities",0],["21.3.3","Outline the process of genetic modification using bacterial production of a human protein as an example, limited to: (a) isolation of the DNA making up a human gene using restriction enzymes, forming sticky ends (b) cutting of bacterial plasmid DNA with the same restriction enzymes, forming complementary sticky ends (c) insertion of human DNA into bacterial plasmid DNA using DNA ligase to form a recombinant plasmid (d) insertion of recombinant plasmids into bacteria (specific details are not required) (e) multiplication of bacteria containing recombinant plasmids (f) expression in bacteria of the human gene to make the human protein",1],["21.3.4","Discuss the advantages and disadvantages of genetically modifying crops, including soya, maize and rice",1]],"21.2":[["21.2.6","Describe how fermenters can be used for the large-scale production of useful products by bacteria and fungi, including insulin, penicillin and mycoprotein",1],["21.2.7","Describe and explain the conditions that need to be controlled in a fermenter, including: temperature, pH, oxygen, nutrient supply and waste products",1]]},"alevel":{"1.1":[["1.1.1","Make temporary preparations of cellular material suitable for viewing with a light microscope",0],["1.1.2","Draw cells from microscope slides and photomicrographs",0]],"1.2":[["1.1.3","Calculate magnifications of images and actual sizes of specimens from drawings, photomicrographs and electron micrographs (scanning and transmission)",0],["1.1.4","Use an eyepiece graticule and stage micrometer scale to make measurements and use the appropriate units, millimetre (mm), micrometre (µm) and nanometre (nm)",0]],"1.3":[["1.1.5","Define resolution and magnification and explain the differences between these terms, with reference to light microscopy and electron microscopy",0]],"1.5":[["1.2.1","Recognise organelles and other cell structures found in eukaryotic cells and outline their structures and functions, limited to: • cell surface membrane • nucleus, nuclear envelope and nucleolus • rough endoplasmic reticulum • smooth endoplasmic reticulum • Golgi body (Golgi apparatus or Golgi complex) • mitochondria (including the presence of small circular DNA) • ribosomes (80S in the cytoplasm and 70S in chloroplasts and mitochondria) • lysosomes • centrioles and microtubules • cilia • microvilli • chloroplasts (including the presence of small circular DNA) • cell wall • plasmodesmata • large permanent vacuole and tonoplast of plant cells",0]],"1.6":[["1.2.2","Describe and interpret photomicrographs, electron micrographs and drawings of typical plant and animal cells",0],["1.2.3","Compare the structure of typical plant and animal cells",0],["1.2.4","State that cells use ATP from respiration for energy-requiring processes",0]],"1.7":[["1.2.5","Outline key structural features of a prokaryotic cell as found in a typical bacterium, including: • unicellular • generally 1–5 µm diameter • peptidoglycan cell walls • circular DNA • 70S ribosomes • absence of organelles surrounded by double membranes",0],["1.2.6","Compare the structure of a prokaryotic cell as found in a typical bacterium with the structures of typical eukaryotic cells in plants and animals",0],["1.2.7","State that all viruses are non-cellular structures with a nucleic acid core (either DNA or RNA) and a capsid made of protein, and that some viruses have an outer envelope made of phospholipids",0]],"2.1":[["2.1.1","Describe and carry out the Benedict’s test for reducing sugars, the iodine test for starch, the emulsion test for lipids and the biuret test for proteins",0],["2.1.3","Describe and carry out a test to identify the presence of non-reducing sugars, using acid hydrolysis and Benedict’s solution",0]],"2.2":[["2.1.2","Describe and carry out a semi-quantitative Benedict’s test on a reducing sugar solution by standardising the test and using the results (time to first colour change or comparison to colour standards) to estimate the concentration",0]],"2.3":[["2.2.1","Describe and draw the ring forms of α-glucose and β-glucose",0],["2.2.2","Define the terms monomer, polymer, macromolecule, monosaccharide, disaccharide and polysaccharide",0],["2.2.3","State the role of covalent bonds in joining smaller molecules together to form polymers",0],["2.2.10","Relate the molecular structure of triglycerides to their functions in living organisms",0]],"2.5":[["2.2.4","State that glucose, fructose and maltose are reducing sugars and that sucrose is a non-reducing sugar",0],["2.2.5","Describe the formation of a glycosidic bond by condensation, with reference to disaccharides, including sucrose, and polysaccharides",0],["2.2.6","Describe the breakage of a glycosidic bond in polysaccharides and disaccharides by hydrolysis, with reference to the non-reducing sugar test",0]],"2.6":[["2.2.7","Describe the molecular structure of the polysaccharides starch (amylose and amylopectin) and glycogen and relate their structures to their functions in living organisms",0],["2.2.8","Describe the molecular structure of the polysaccharide cellulose and outline how the arrangement of cellulose molecules contributes to the function of plant cell walls",0]],"2.7":[["2.2.9","State that triglycerides are non-polar hydrophobic molecules and describe the molecular structure of triglycerides with reference to fatty acids (saturated and unsaturated), glycerol and the formation of ester bonds",0]],"2.8":[["2.2.11","Describe the molecular structure of phospholipids with reference to their hydrophilic (polar) phosphate heads and hydrophobic (non-polar) fatty acid tails",0]],"2.9":[["2.3.1","Describe and draw the general structure of an amino acid and the formation and breakage of a peptide bond",0],["2.3.2","Explain the meaning of the terms primary structure, secondary structure, tertiary structure and quaternary structure of proteins",0]],"2.10":[["2.3.3","Describe the types of interaction that hold protein molecules in shape: • hydrophobic interactions • hydrogen bonding • ionic bonding • covalent bonding, including disulfide bonds",0],["2.3.4","State that globular proteins are generally soluble and have physiological roles and fibrous proteins are generally insoluble and have structural roles",0]],"2.11":[["2.3.5","Describe the structure of a molecule of haemoglobin as an example of a globular protein, including the formation of its quaternary structure from two alpha (α) chains (α–globin), two beta (β) chains (β–globin) and a haem group",0],["2.3.6","Relate the structure of haemoglobin to its function, including the importance of iron in the haem group",0],["2.3.7","Describe the structure of a molecule of collagen as an example of a fibrous protein, and the arrangement of collagen molecules to form collagen fibres",0],["2.3.8","Relate the structures of collagen molecules and collagen fibres to their function",0]],"2.13":[["2.4.1","Explain how hydrogen bonding occurs between water molecules and relate the properties of water to its roles in living organisms, limited to solvent action, high specific heat capacity and latent heat of vaporisation",0]],"3.1":[["3.1.1","State that enzymes are globular proteins that catalyse reactions inside cells (intracellular enzymes) or are secreted to catalyse reactions outside cells (extracellular enzymes)",0]],"3.2":[["3.1.2","Explain the mode of action of enzymes in terms of an active site, enzyme–substrate complex, lowering of activation energy and enzyme specificity, including the lock-and-key hypothesis and the induced-fit hypothesis",0],["3.1.3","Investigate the progress of enzyme-catalysed reactions by measuring rates of formation of products using catalase and rates of disappearance of substrate using amylase",0],["3.1.4","Outline the use of a colorimeter for measuring the progress of enzyme-catalysed reactions that involve colour changes",0]],"3.3":[["3.2.1","Investigate and explain the effects of the following factors on the rate of enzyme-catalysed reactions: • temperature • pH (using buffer solutions) • enzyme concentration • substrate concentration • inhibitor concentration",0]],"3.4":[["3.2.2","Explain that the maximum rate of reaction (Vmax) is used to derive the Michaelis–Menten constant (Km), which is used to compare the affinity of different enzymes for their substrates",0],["3.2.3","Explain the effects of reversible inhibitors, both competitive and non-competitive, on enzyme activity",0]],"3.5":[["3.2.4","Investigate the difference in activity between an enzyme immobilised in alginate and the same enzyme free in solution, and state the advantages of using immobilised enzymes",0]],"4.1":[["4.1.1","Describe the fluid mosaic model of membrane structure with reference to the hydrophobic and hydrophilic interactions that account for the formation of the phospholipid bilayer and the arrangement of proteins",0]],"4.2":[["4.1.2","Describe the arrangement of cholesterol, glycolipids and glycoproteins in cell surface membranes",0],["4.1.3","Describe the roles of phospholipids, cholesterol, glycolipids, proteins and glycoproteins in cell surface membranes, with reference to stability, fluidity, permeability, transport (carrier proteins and channel proteins), cell signalling (cell surface receptors) and cell recognition (cell surface antigens – see 11.1.2)",0]],"4.3":[["4.1.4","Outline the main stages in the process of cell signalling leading to specific responses: • secretion of specific chemicals (ligands) from cells • transport of ligands to target cells • binding of ligands to cell surface receptors on target cells",0]],"4.6":[["4.2.1","Describe and explain the processes of simple diffusion, facilitated diffusion, osmosis, active transport, endocytosis and exocytosis",0]],"4.8":[["4.2.2","Investigate simple diffusion and osmosis using plant tissue and non-living materials, including dialysis (Visking) tubing and agar",0],["4.2.5","Investigate the effects of immersing plant tissues in solutions of different water potentials, using the results to estimate the water potential of the tissues",0]],"4.4":[["4.2.3","Illustrate the principle that surface area to volume ratios decrease with increasing size by calculating surface areas and volumes of simple 3-D shapes (as shown in the Mathematical requirements)",0]],"4.7":[["4.2.4","Investigate the effect of changing surface area to volume ratio on diffusion using agar blocks of different sizes",0]],"4.5":[["4.2.6","Explain the movement of water between cells and solutions in terms of water potential and explain the different effects of the movement of water on plant cells and animal cells (knowledge of solute potential and pressure potential is not expected)",0]],"5.1":[["5.1.1","Describe the structure of a chromosome, limited to: • DNA • histone proteins • sister chromatids • centromere • telomeres",0],["5.1.2","Explain the importance of mitosis in the production of genetically identical daughter cells during: • growth of multicellular organisms • replacement of damaged or dead cells • repair of tissues by cell replacement • asexual reproduction",0]],"5.2":[["5.1.3","Outline the mitotic cell cycle, including: • interphase (growth in G1 and G2 phases and DNA replication in S phase) • mitosis • cytokinesis",0],["5.2.1","Describe the behaviour of chromosomes in plant and animal cells during the mitotic cell cycle and the associated behaviour of the nuclear envelope, the cell surface membrane and the spindle (names of the main stages of mitosis are expected: prophase, metaphase, anaphase and telophase)",0]],"5.3":[["5.1.4","Outline the role of telomeres in preventing the loss of genes from the ends of chromosomes during DNA replication",0],["5.1.5","Outline the role of stem cells in cell replacement and tissue repair by mitosis",0]],"5.4":[["5.1.6","Explain how uncontrolled cell division can result in the formation of a tumour",0]],"5.6":[["5.2.2","Interpret photomicrographs, diagrams and microscope slides of cells in different stages of the mitotic cell cycle and identify the main stages of mitosis",0]],"6.1":[["6.1.1","Describe the structure of nucleotides, including the phosphorylated nucleotide ATP (structural formulae are not expected)",0],["6.1.2","State that the bases adenine and guanine are purines with a double ring structure, and that the bases cytosine, thymine and uracil are pyrimidines with a single ring structure (structural formulae for bases are not expected)",0],["6.1.3","Describe the structure of a DNA molecule as a double helix, including: • the importance of complementary base pairing between the 5′ to 3′ strand and the 3′ to 5′ strand (antiparallel strands) • differences in hydrogen bonding between C–G and A–T base pairs • linking of nucleotides by phosphodiester bonds",0],["6.1.4","Describe the semi-conservative replication of DNA during the S phase of the cell cycle, including: • the roles of DNA polymerase and DNA ligase (knowledge of other enzymes in DNA replication in cells and different types of DNA polymerase is not expected) • the differences between leading strand and lagging strand replication as a consequence of DNA polymerase adding nucleotides only in a 5′ to 3′ direction",0],["6.1.5","Describe the structure of an RNA molecule, using the example of messenger RNA (mRNA)",0]],"6.2":[["6.2.1","State that a polypeptide is coded for by a gene and that a gene is a sequence of nucleotides that forms part of a DNA molecule",0],["6.2.2","Describe the principle of the universal genetic code in which different triplets of DNA bases either code for specific amino acids or correspond to start and stop codons",0],["6.2.3","Describe how the information in DNA is used during transcription and translation to construct polypeptides, including the roles of: • RNA polymerase • messenger RNA (mRNA) • codons • transfer RNA (tRNA) • anticodons • ribosomes",0],["6.2.4","State that the strand of a DNA molecule that is used in transcription is called the transcribed or template strand and that the other strand is called the non-transcribed strand",0],["6.2.5","Explain that, in eukaryotes, the RNA molecule formed following transcription (primary transcript) is modified by the removal of non-coding sequences (introns) and the joining together of coding sequences (exons) to form mRNA",0],["6.2.6","State that a gene mutation is a change in the sequence of base pairs in a DNA molecule that may result in an altered polypeptide",0],["6.2.7","Explain that a gene mutation is a result of substitution or deletion or insertion of nucleotides in DNA and outline how each of these types of mutation may affect the polypeptide produced",0]],"7.1":[["7.1.1","Draw plan diagrams of transverse sections of stems, roots and leaves of herbaceous dicotyledonous plants from microscope slides and photomicrographs",0],["7.1.2","Describe the distribution of xylem and phloem in transverse sections of stems, roots and leaves of herbaceous dicotyledonous plants",0],["7.1.3","Draw and label xylem vessel elements, phloem sieve tube elements and companion cells from microscope slides, photomicrographs and electron micrographs",0],["7.1.4","Relate the structure of xylem vessel elements, phloem sieve tube elements and companion cells to their functions",0],["7.2.1","State that some mineral ions and organic compounds can be transported within plants dissolved in water",0]],"7.2":[["7.2.2","Describe the transport of water from the soil to the xylem through the: • apoplast pathway, including reference to lignin and cellulose • symplast pathway, including reference to the endodermis, Casparian strip and suberin",0],["7.2.3","Explain that transpiration involves the evaporation of water from the internal surfaces of leaves followed by diffusion of water vapour to the atmosphere",0],["7.2.4","Explain how hydrogen bonding of water molecules is involved with movement of water in the xylem by cohesion-tension in transpiration pull and by adhesion to cellulose in cell walls",0],["7.2.5","Make annotated drawings of transverse sections of leaves from xerophytic plants to explain how they are adapted to reduce water loss by transpiration",0],["7.2.6","State that assimilates dissolved in water, such as sucrose and amino acids, move from sources to sinks in phloem sieve tubes",0],["7.2.7","Explain how companion cells transfer assimilates to phloem sieve tubes, with reference to proton pumps and cotransporter proteins",0],["7.2.8","Explain mass flow in phloem sieve tubes down a hydrostatic pressure gradient from source to sink",0]],"8.1":[["8.1.1","State that the mammalian circulatory system is a closed double circulation consisting of a heart, blood and blood vessels including arteries, arterioles, capillaries, venules and veins",0],["8.1.3","Recognise arteries, veins and capillaries from microscope slides, photomicrographs and electron micrographs and make plan diagrams showing the structure of arteries and veins in transverse section (TS) and longitudinal section (LS)",0],["8.1.4","Explain how the structure of muscular arteries, elastic arteries, veins and capillaries are each related to their functions",0],["8.1.5","Recognise and draw red blood cells, monocytes, neutrophils and lymphocytes from microscope slides, photomicrographs and electron micrographs",0],["8.1.6","State that water is the main component of blood and tissue fluid and relate the properties of water to its role in transport in mammals, limited to solvent action and high specific heat capacity",0],["8.1.7","State the functions of tissue fluid and describe the formation of tissue fluid in a capillary network",0],["8.2.3","Describe the role of plasma in the transport of carbon dioxide",0]],"8.3":[["8.1.2","Describe the functions of the main blood vessels of the pulmonary and systemic circulations, limited to pulmonary artery, pulmonary vein, aorta and vena cava",0],["8.3.1","Describe the external and internal structure of the mammalian heart",0],["8.3.2","Explain the differences in the thickness of the walls of the: • atria and ventricles • left ventricle and right ventricle",0],["8.3.3","Describe the cardiac cycle, with reference to the relationship between blood pressure changes during systole and diastole and the opening and closing of valves",0],["8.3.4","Explain the roles of the sinoatrial node, the atrioventricular node and the Purkyne tissue in the cardiac cycle (knowledge of nervous and hormonal control is not expected)",0]],"8.2":[["8.2.1","Describe the role of red blood cells in transporting oxygen and carbon dioxide with reference to the roles of: • haemoglobin • carbonic anhydrase • the formation of haemoglobinic acid • the formation of carbaminohaemoglobin",0],["8.2.2","Describe the chloride shift and explain the importance of the chloride shift",0],["8.2.4","Describe and explain the oxygen dissociation curve of adult haemoglobin",0],["8.2.5","Explain the importance of the oxygen dissociation curve at partial pressures of oxygen in the lungs and in respiring tissues",0],["8.2.6","Describe the Bohr shift and explain the importance of the Bohr shift",0]],"9.1":[["9.1.1","Describe the structure of the human gas exchange system, limited to: • lungs • trachea • bronchi • bronchioles • alveoli • capillary network",0],["9.1.2","Describe the distribution in the gas exchange system of cartilage, ciliated epithelium, goblet cells, squamous epithelium of alveoli, smooth muscle and capillaries",0],["9.1.3","Recognise cartilage, ciliated epithelium, goblet cells, squamous epithelium of alveoli, smooth muscle and capillaries in microscope slides, photomicrographs and electron micrographs",0],["9.1.4","Recognise trachea, bronchi, bronchioles and alveoli in microscope slides, photomicrographs and electron micrographs and make plan diagrams of transverse sections of the walls of the trachea and bronchus",0],["9.1.5","Describe the functions of ciliated epithelial cells, goblet cells and mucous glands in maintaining the health of the gas exchange system",0],["9.1.6","Describe the functions in the gas exchange system of cartilage, smooth muscle, elastic fibres and squamous epithelium",0],["9.1.7","Describe gas exchange between air in the alveoli and blood in the capillaries",0]],"10.1":[["10.1.1","State that infectious diseases are caused by pathogens and are transmissible",0],["10.1.2","State the name and type of pathogen that causes each of the following diseases: • cholera – caused by the bacterium Vibrio cholerae • malaria – caused by the protoctists Plasmodium falciparum, Plasmodium malariae, Plasmodium ovale and Plasmodium vivax • tuberculosis (TB) – caused by the bacteria Mycobacterium tuberculosis and Mycobacterium bovis • HIV/AIDS – caused by the human immunodeficiency virus (HIV)",0],["10.1.3","Explain how cholera, malaria, TB and HIV are transmitted",0],["10.1.4","Discuss the biological, social and economic factors that need to be considered in the prevention and control of cholera, malaria, TB and HIV (details of the life cycle of the malarial parasite are not expected)",0]],"10.2":[["10.2.1","Outline how penicillin acts on bacteria and why antibiotics do not affect viruses",0],["10.2.2","Discuss the consequences of antibiotic resistance and the steps that can be taken to reduce its impact",0]],"11.1":[["11.1.1","Describe the mode of action of phagocytes (macrophages and neutrophils)",0],["11.1.2","Explain what is meant by an antigen (see 4.1.3) and state the difference between self antigens and non-self antigens",0],["11.1.4","Explain the role of memory cells in the secondary immune response and in long-term immunity",0],["11.2.1","Relate the molecular structure of antibodies to their functions",0]],"11.2":[["11.1.3","Describe the sequence of events that occurs during a primary immune response with reference to the roles of: • macrophages • B-lymphocytes, including plasma cells • T-lymphocytes, limited to T-helper cells and T-killer cells",0],["11.2.2","Outline the hybridoma method for the production of monoclonal antibodies",0],["11.2.3","Outline the principles of using monoclonal antibodies in the diagnosis of disease and in the treatment of disease",0],["11.2.4","Describe the differences between active immunity and passive immunity and between natural immunity and artificial immunity",0],["11.2.5","Explain that vaccines contain antigens that stimulate immune responses to provide long-term immunity",0],["11.2.6","Explain how vaccination programmes can help to control the spread of infectious diseases",0]],"12.1":[["12.1.1","Outline the need for energy in living organisms, as illustrated by active transport, movement and anabolic reactions, such as those occurring in DNA replication and protein synthesis",0],["12.1.2","Describe the features of ATP that make it suitable as the universal energy currency",0],["12.1.3","State that ATP is synthesised by: • transfer of phosphate in substrate-linked reactions • chemiosmosis in membranes of mitochondria and chloroplasts",0],["12.1.4","Explain the relative energy values of carbohydrates, lipids and proteins as respiratory substrates",0],["12.1.5","State that the respiratory quotient (RQ) is the ratio of the number of molecules of carbon dioxide produced to the number of molecules of oxygen taken in, as a result of respiration",0],["12.1.6","Calculate RQ values of different respiratory substrates from equations for respiration",0],["12.2.7","Describe the role of NAD and FAD in transferring hydrogen to carriers in the inner mitochondrial membrane",0],["12.2.14","Describe and carry out investigations using simple respirometers to determine the effect of temperature on the rate of respiration",0]],"12.2":[["12.1.7","Describe and carry out investigations, using simple respirometers, to determine the RQ of germinating seeds or small invertebrates (e.g. blowfly larvae)",0],["12.2.1","State where each of the four stages in aerobic respiration occurs in eukaryotic cells: • glycolysis in the cytoplasm • link reaction in the mitochondrial matrix • Krebs cycle in the mitochondrial matrix • oxidative phosphorylation on the inner membrane of mitochondria",0],["12.2.2","Outline glycolysis as phosphorylation of glucose and the subsequent splitting of fructose 1,6-bisphosphate (6C) into two triose phosphate molecules (3C), which are then further oxidised to pyruvate (3C), with the production of ATP and reduced NAD",0],["12.2.3","Explain that, when oxygen is available, pyruvate enters mitochondria to take part in the link reaction",0],["12.2.4","Describe the link reaction, including the role of coenzyme A in the transfer of acetyl (2C) groups",0],["12.2.5","Outline the Krebs cycle, explaining that oxaloacetate (4C) acts as an acceptor of the 2C fragment from acetyl coenzyme A to form citrate (6C), which is converted back to oxaloacetate in a series of small steps",0],["12.2.6","Explain that reactions in the Krebs cycle involve decarboxylation and dehydrogenation and the reduction of the coenzymes NAD and FAD",0],["12.2.8","Explain that during oxidative phosphorylation: • hydrogen atoms split into protons and energetic electrons • energetic electrons release energy as they pass through the electron transport chain (details of carriers are not expected) • the released energy is used to transfer protons across the inner mitochondrial membrane • protons return to the mitochondrial matrix by facilitated diffusion through ATP synthase, providing energy for ATP synthesis (details of ATP synthase are not expected) • oxygen acts as the final electron acceptor to form water",0],["12.2.9","Describe the relationship between the structure and function of mitochondria using diagrams and electron micrographs",0],["12.2.10","Outline respiration in anaerobic conditions in mammals (lactate fermentation) and in yeast cells (ethanol fermentation)",0],["12.2.11","Explain why the energy yield from respiration in aerobic conditions is much greater than the energy yield from respiration in anaerobic conditions (a detailed account of the total yield of ATP from the aerobic respiration of glucose is not expected)",0],["12.2.12","Explain how rice is adapted to grow with its roots submerged in water, limited to the development of aerenchyma in roots, ethanol fermentation in roots and faster growth of stems",0],["12.2.13","Describe and carry out investigations using redox indicators, including DCPIP and methylene blue, to determine the effects of temperature and substrate concentration on the rate of respiration of yeast",0]],"13.2":[["13.1.1","Describe the relationship between the structure of chloroplasts, as shown in diagrams and electron micrographs, and their function",0],["13.2.1","State that light intensity, carbon dioxide concentration and temperature are examples of limiting factors of photosynthesis",0],["13.2.2","Explain the effects of changes in light intensity, carbon dioxide concentration and temperature on the rate of photosynthesis",0],["13.2.3","Describe and carry out investigations using redox indicators, including DCPIP and methylene blue, and a suspension of chloroplasts to determine the effects of light intensity and light wavelength on the rate of photosynthesis",0],["13.2.4","Describe and carry out investigations using whole plants, including aquatic plants, to determine the effects of light intensity, carbon dioxide concentration and temperature on the rate of photosynthesis",0]],"13.1":[["13.1.2","Explain that energy transferred as ATP and reduced NADP from the light-dependent stage is used during the light- independent stage (Calvin cycle) of photosynthesis to produce complex organic molecules",0],["13.1.3","State that within a chloroplast, the thylakoids (thylakoid membranes and thylakoid spaces), which occur in stacks called grana, are the site of the light-dependent stage and the stroma is the site of the light-independent stage",0],["13.1.4","Describe the role of chloroplast pigments (chlorophyll a, chlorophyll b, carotene and xanthophyll) in light absorption in thylakoids",0],["13.1.5","Interpret absorption spectra of chloroplast pigments and action spectra for photosynthesis",0],["13.1.6","Describe and use chromatography to separate and identify chloroplast pigments (reference should be made to Rf values in identification of chloroplast pigments)",0],["13.1.7","State that cyclic photophosphorylation and non-cyclic photophosphorylation occur during the light-dependent stage of photosynthesis",0],["13.1.8","Explain that in cyclic photophosphorylation: • only photosystem I (PSI) is involved • photoactivation of chlorophyll occurs • ATP is synthesised",0],["13.1.9","Explain that in non-cyclic photophosphorylation: • photosystem I (PSI) and photosystem II (PSII) are both involved • photoactivation of chlorophyll occurs • the oxygen-evolving complex catalyses the photolysis of water • ATP and reduced NADP are synthesised",0],["13.1.10","Explain that during photophosphorylation: • energetic electrons release energy as they pass through the electron transport chain (details of carriers are not expected) • the released energy is used to transfer protons across the thylakoid membrane • protons return to the stroma from the thylakoid space by facilitated diffusion through ATP synthase, providing energy for ATP synthesis (details of ATP synthase are not expected)",0],["13.1.11","Outline the three main stages of the Calvin cycle: • rubisco catalyses the fixation of carbon dioxide by combination with a molecule of ribulose bisphosphate (RuBP), a 5C compound, to yield two molecules of glycerate 3-phosphate (GP), a 3C compound • GP is reduced to triose phosphate (TP) in reactions involving reduced NADP and ATP • RuBP is regenerated from TP in reactions that use ATP",0],["13.1.12","State that Calvin cycle intermediates are used to produce other molecules, limited to GP to produce some amino acids and TP to produce carbohydrates, lipids and amino acids",0]],"14.1":[["14.1.1","Explain what is meant by homeostasis and the importance of homeostasis in mammals",0],["14.1.2","Explain the principles of homeostasis in terms of internal and external stimuli, receptors, coordination systems (nervous system and endocrine system), effectors (muscles and glands) and negative feedback",0],["14.1.3","State that urea is produced in the liver from the deamination of excess amino acids",0],["14.1.4","Describe the structure of the human kidney, limited to: • fibrous capsule • cortex • medulla • renal pelvis • ureter • branches of the renal artery and renal vein",0],["14.1.5","Identify, in diagrams, photomicrographs and electron micrographs, the parts of a nephron and its associated blood vessels and structures, limited to: • glomerulus • Bowman’s capsule • proximal convoluted tubule • loop of Henle • distal convoluted tubule • collecting duct",0],["14.1.6","Describe and explain the formation of urine in the nephron, limited to: • the formation of glomerular filtrate by ultrafiltration in the Bowman’s capsule • selective reabsorption in the proximal convoluted tubule",0],["14.1.7","Relate the detailed structure of the Bowman’s capsule and proximal convoluted tubule to their functions in the formation of urine",0],["14.1.8","Describe the roles of the hypothalamus, posterior pituitary gland, antidiuretic hormone (ADH), aquaporins and collecting ducts in osmoregulation",0],["14.1.9","Describe the principles of cell signalling using the example of the control of blood glucose concentration by glucagon, limited to: • binding of hormone to cell surface receptor causing conformational change • activation of G-protein leading to stimulation of adenylyl cyclase • formation of the second messenger, cyclic AMP (cAMP) • activation of protein kinase A by cAMP leading to initiation of an enzyme cascade • amplification of the signal through the enzyme cascade as a result of activation of more and more enzymes by phosphorylation • cellular response in which the final enzyme in the pathway is activated, catalysing the breakdown of glycogen",0],["14.1.10","Explain how negative feedback control mechanisms regulate blood glucose concentration, with reference to the effects of insulin on muscle cells and liver cells and the effect of glucagon on liver cells",0],["14.1.11","Explain the principles of operation of test strips and biosensors for measuring the concentration of glucose in blood and urine, with reference to glucose oxidase and peroxidase enzymes",0]],"14.2":[["14.2.1","Explain that stomata respond to changes in environmental conditions by opening and closing and that regulation of stomatal aperture balances the need for carbon dioxide uptake by diffusion with the need to minimise water loss by transpiration",0],["14.2.2","Explain that stomata have daily rhythms of opening and closing",0],["14.2.3","Describe the structure and function of guard cells and explain the mechanism by which they open and close stomata",0],["14.2.4","Describe the role of abscisic acid in the closure of stomata during times of water stress, including the role of calcium ions as a second messenger",0]],"15.1":[["15.1.1","Describe the features of the endocrine system with reference to the hormones ADH, glucagon and insulin (see 14.1.8, 14.1.9 and 14.1.10)",0],["15.1.2","Compare the features of the nervous system and the endocrine system",0],["15.1.3","Describe the structure and function of a sensory neurone and a motor neurone and state that intermediate neurones connect sensory neurones and motor neurones",0],["15.1.4","Outline the role of sensory receptor cells in detecting stimuli and stimulating the transmission of impulses in sensory neurones",0],["15.1.5","Describe the sequence of events that results in an action potential in a sensory neurone, using a chemoreceptor cell in a human taste bud as an example",0],["15.1.6","Describe and explain changes to the membrane potential of neurones, including: • how the resting potential is maintained • the events that occur during an action potential • how the resting potential is restored during the refractory period",0],["15.1.7","Describe and explain the rapid transmission of an impulse in a myelinated neurone with reference to saltatory conduction",0],["15.1.8","Explain the importance of the refractory period in determining the frequency of impulses",0],["15.1.9","Describe the structure of a cholinergic synapse and explain how it functions, including the role of calcium ions",0],["15.1.10","Describe the roles of neuromuscular junctions, the T-tubule system and sarcoplasmic reticulum in stimulating contraction in striated muscle",0],["15.1.11","Describe the ultrastructure of striated muscle with reference to sarcomere structure using electron micrographs and diagrams",0],["15.1.12","Explain the sliding filament model of muscular contraction including the roles of troponin, tropomyosin, calcium ions and ATP",0]],"15.2":[["15.2.1","Describe the rapid response of the Venus fly trap to stimulation of hairs on the lobes of modified leaves and explain how the closure of the trap is achieved",0],["15.2.2","Explain the role of auxin in elongation growth by stimulating proton pumping to acidify cell walls",0],["15.2.3","Describe the role of gibberellin in the germination of barley (see 16.3.4)",0]],"16.1":[["16.1.1","Explain the meanings of the terms haploid (n) and diploid (2n)",0],["16.1.2","Explain what is meant by homologous pairs of chromosomes",0],["16.1.3","Explain the need for a reduction division during meiosis in the production of gametes",0],["16.1.4","Describe the behaviour of chromosomes in plant and animal cells during meiosis and the associated behaviour of the nuclear envelope, the cell surface membrane and the spindle (names of the main stages of meiosis, but not the sub-divisions of prophase I, are expected: prophase I, metaphase I, anaphase I, telophase I, prophase II, metaphase II, anaphase II and telophase II)",0],["16.1.5","Interpret photomicrographs and diagrams of cells in different stages of meiosis and identify the main stages of meiosis",0],["16.1.6","Explain that crossing over and random orientation (independent assortment) of pairs of homologous chromosomes and sister chromatids during meiosis produces genetically different gametes",0],["16.1.7","Explain that the random fusion of gametes at fertilisation produces genetically different individuals",0]],"16.2":[["16.2.1","Explain the terms gene, locus, allele, dominant, recessive, codominant, linkage, test cross, F1, F2, phenotype, genotype, homozygous and heterozygous",0],["16.2.2","Interpret and construct genetic diagrams, including Punnett squares, to explain and predict the results of monohybrid crosses and dihybrid crosses that involve dominance, codominance, multiple alleles and sex linkage",0],["16.2.3","Interpret and construct genetic diagrams, including Punnett squares, to explain and predict the results of dihybrid crosses that involve autosomal linkage and epistasis (knowledge of the expected ratios for different types of epistasis is not expected)",0],["16.2.4","Interpret and construct genetic diagrams, including Punnett squares, to explain and predict the results of test crosses",0],["16.2.5","Use the chi-squared test to test the significance of differences between observed and expected results (the formula for the chi-squared test will be provided, as shown in the Mathematical requirements)",0],["16.2.6","Explain the relationship between genes, proteins and phenotype with respect to the: • TYR gene, tyrosinase and albinism • HBB gene, haemoglobin and sickle cell anaemia • F8 gene, factor VIII and haemophilia • HTT gene, huntingtin and Huntington’s disease",0],["16.2.7","Explain the role of gibberellin in stem elongation including the role of the dominant allele, Le, that codes for a functional enzyme in the gibberellin synthesis pathway, and the recessive allele, le, that codes for a non-functional enzyme",0]],"16.3":[["16.3.1","Describe the differences between structural genes and regulatory genes and the differences between repressible enzymes and inducible enzymes",0],["16.3.2","Explain genetic control of protein production in a prokaryote using the lac operon (knowledge of the role of cAMP is not expected)",0],["16.3.3","State that transcription factors are proteins that bind to DNA and are involved in the control of gene expression in eukaryotes by decreasing or increasing the rate of transcription",0],["16.3.4","Explain how gibberellin activates genes by causing the breakdown of DELLA protein repressors, which normally inhibit factors that promote transcription",0]],"17.1":[["17.1.1","Explain, with examples, that phenotypic variation is due to genetic factors or environmental factors or a combination of genetic and environmental factors",0],["17.1.2","Explain what is meant by discontinuous variation and continuous variation",0],["17.1.3","Explain the genetic basis of discontinuous variation and continuous variation",0],["17.1.4","Use the t-test to compare the means of two different samples (the formula for the t-test will be provided, as shown in the Mathematical requirements)",0]],"17.2":[["17.2.1","Explain that natural selection occurs because populations have the capacity to produce many offspring that compete for resources; in the ‘struggle for existence’, individuals that are best adapted are most likely to survive to reproduce and pass on their alleles to the next generation",0],["17.2.2","Explain how environmental factors can act as stabilising, disruptive and directional forces of natural selection",0],["17.2.3","Explain how selection, the founder effect and genetic drift, including the bottleneck effect, may affect allele frequencies in populations",0],["17.2.4","Outline how bacteria become resistant to antibiotics as an example of natural selection",0],["17.2.5","Use the Hardy–Weinberg principle to calculate allele and genotype frequencies in populations and state the conditions when this principle can be applied (the two equations for the Hardy–Weinberg principle will be provided, as shown in the Mathematical requirements)",0],["17.2.6","Describe the principles of selective breeding (artificial selection)",0],["17.2.7","Outline the following examples of selective breeding: • the introduction of disease resistance to varieties of wheat and rice • inbreeding and hybridisation to produce vigorous, uniform varieties of maize • improving the milk yield of dairy cattle",0]],"17.3":[["17.3.1","Outline the theory of evolution as a process leading to the formation of new species from pre-existing species over time, as a result of changes to gene pools from generation to generation",0],["17.3.2","Discuss how DNA sequence data can show evolutionary relationships between species",0],["17.3.3","Explain how speciation may occur as a result of genetic isolation by: • geographical separation (allopatric speciation) • ecological and behavioural separation (sympatric speciation)",0]],"18.1":[["18.1.1","Discuss the meaning of the term species, limited to the biological species concept, morphological species concept and ecological species concept",0],["18.1.2","Describe the classification of organisms into three domains: Archaea, Bacteria and Eukarya",0],["18.1.3","State that Archaea and Bacteria are prokaryotes and that there are differences between them, limited to differences in membrane lipids, ribosomal RNA and composition of cell walls",0],["18.1.4","Describe the classification of organisms in the Eukarya domain into the taxonomic hierarchy of kingdom, phylum, class, order, family, genus and species",0],["18.1.5","Outline the characteristic features of the kingdoms Protoctista, Fungi, Plantae and Animalia",0],["18.1.6","Outline how viruses are classified, limited to the type of nucleic acid (RNA or DNA) and whether this is single stranded or double stranded",0]],"18.2":[["18.2.1","Define the terms ecosystem and niche",0],["18.2.2","Explain that biodiversity can be assessed at different levels, including: • the number and range of different ecosystems and habitats • the number of species and their relative abundance • the genetic variation within each species",0],["18.2.3","Explain the importance of random sampling in determining the biodiversity of an area",0],["18.2.4","Describe and use suitable methods to assess the distribution and abundance of organisms in an area, limited to frame quadrats, line transects, belt transects and mark-release- recapture using the Lincoln index (the formula for the Lincoln index will be provided, as shown in the Mathematical requirements)",0],["18.2.5","Use Spearman’s rank correlation and Pearson’s linear correlation to analyse the relationships between two variables, including how biotic and abiotic factors affect the distribution and abundance of species (the formulae for these correlations will be provided, as shown in the Mathematical requirements)",0],["18.2.6","Use Simpson’s index of diversity (D) to calculate the biodiversity of an area, and state the significance of different values of D (the formula for Simpson’s index of diversity will be provided, as shown in the Mathematical requirements)",0],["18.3.1","Explain why populations and species can become extinct as a result of: • climate change • competition • hunting by humans • degradation and loss of habitats",0],["18.3.2","Outline reasons for the need to maintain biodiversity",0],["18.3.3","Outline the roles of zoos, botanic gardens, conserved areas (including national parks and marine parks), ‘frozen zoos’ and seed banks, in the conservation of endangered species",0],["18.3.4","Describe methods of assisted reproduction used in the conservation of endangered mammals, limited to IVF, embryo transfer and surrogacy",0],["18.3.5","Explain reasons for controlling invasive alien species",0],["18.3.6","Outline the role in conservation of the International Union for Conservation of Nature (IUCN) and the Convention on International Trade in Endangered Species of Wild Fauna and Flora (CITES)",0]],"19.1":[["19.1.1","Define the term recombinant DNA",0],["19.1.2","Explain that genetic engineering is the deliberate manipulation of genetic material to modify specific characteristics of an organism and that this may involve transferring a gene into an organism so that the gene is expressed",0],["19.1.3","Explain that genes to be transferred into an organism may be: • extracted from the DNA of a donor organism • synthesised from the mRNA of a donor organism • synthesised chemically from nucleotides",0],["19.1.4","Explain the roles of restriction endonucleases, DNA ligase, plasmids, DNA polymerase and reverse transcriptase in the transfer of a gene into an organism",0],["19.1.5","Explain why a promoter may have to be transferred into an organism as well as the desired gene",0],["19.1.6","Explain how gene expression may be confirmed by the use of marker genes coding for fluorescent products",0],["19.1.7","Explain that gene editing is a form of genetic engineering involving the insertion, deletion or replacement of DNA at specific sites in the genome",0],["19.1.8","Describe and explain the steps involved in the polymerase chain reaction (PCR) to clone and amplify DNA, including the role of Taq polymerase",0],["19.1.9","Describe and explain how gel electrophoresis is used to separate DNA fragments of different lengths",0],["19.1.10","Outline how microarrays are used in the analysis of genomes and in detecting mRNA in studies of gene expression",0],["19.1.11","Outline the benefits of using databases that provide information about nucleotide sequences of genes and genomes, and amino acid sequences of proteins and protein structures",0]],"19.2":[["19.2.1","Explain the advantages of using recombinant human proteins to treat disease, using the examples insulin, factor VIII and adenosine deaminase",0],["19.2.2","Outline the advantages of genetic screening, using the examples of breast cancer (BRCA1 and BRCA2), Huntington’s disease and cystic fibrosis",0],["19.2.3","Outline how genetic diseases can be treated with gene therapy, using the examples severe combined immunodeficiency (SCID) and inherited eye diseases",0],["19.2.4","Discuss the social and ethical considerations of using genetic screening and gene therapy in medicine",0]],"19.3":[["19.3.1","Explain that genetic engineering may help to solve the global demand for food by improving the quality and productivity of farmed animals and crop plants, using the examples of GM salmon, herbicide resistance in soybean and insect resistance in cotton",0],["19.3.2","Discuss the ethical and social implications of using genetically modified organisms (GMOs) in food production",0]]}};
const GAP={"alevel":{"18.2":{"notes":"\n<h4>18.3 Conservation of biodiversity (syllabus 18.3)</h4>\n<h5>Why populations and species become extinct (18.3.1)</h5>\n<ul><li><b>Climate change</b>: temperature and rainfall patterns shift faster than many species can adapt or move. Examples: coral bleaching as seas warm, polar bears losing sea ice.</li>\n<li><b>Competition</b>: introduced or invasive species may compete better for food, light, water or space, so native species decline.</li>\n<li><b>Hunting by humans</b> (over-exploitation): animals taken faster than they can reproduce, for meat, skins, horn or ivory. Examples: passenger pigeon, black rhinoceros.</li>\n<li><b>Degradation and loss of habitats</b>: deforestation, drainage of wetlands, farming, building and pollution. Habitats are also broken into small fragments, so populations become small, lose genetic diversity and are more likely to die out.</li></ul>\n<h5>Reasons for maintaining biodiversity (18.3.2)</h5>\n<ul><li><b>Ecological</b>: species depend on each other (food webs, pollination, nutrient cycling). Losing one species can destabilise a whole ecosystem.</li><li><b>Economic</b>: food crops, timber, fish, medicines and tourism all depend on wild species and their genes.</li><li><b>Ethical and aesthetic</b>: every species has a right to exist, and people value natural beauty.</li></ul>\n<h5>Roles of zoos, botanic gardens, conserved areas, frozen zoos and seed banks (18.3.3)</h5>\n<ul><li><b>Zoos</b> (<i>ex situ</i>): captive breeding of endangered animals, with studbooks to avoid inbreeding, then release to the wild where possible (for example the Arabian oryx). They also do research and education.</li>\n<li><b>Botanic gardens</b> (<i>ex situ</i>): grow and propagate rare plants, keep living collections, carry out research and educate the public.</li>\n<li><b>Conserved areas</b> such as national parks and marine parks (<i>in situ</i>): protect whole habitats and every species in them, using legal protection, ranger patrols and controls on hunting, fishing and building.</li>\n<li><b>Frozen zoos</b>: store eggs, sperm, embryos and tissue cells in liquid nitrogen at about &minus;196&nbsp;&deg;C. The genetic material can be used later for assisted reproduction, so genetic diversity is not lost.</li>\n<li><b>Seed banks</b>: seeds are dried and stored at low temperature, so thousands of species take up little space and stay alive for many years. Samples are germinated now and then to renew the stock. Some seeds cannot survive drying or freezing, so this method does not work for every species.</li></ul>\n<h5>Assisted reproduction (18.3.4)</h5>\n<ul><li><b>IVF (in vitro fertilisation)</b>: eggs are collected from a female (often after hormone treatment), fertilised with sperm in a dish, and the early embryos are grown for a short time.</li>\n<li><b>Embryo transfer</b>: embryos are placed in the uterus of a female so they can develop to birth. They can be frozen first.</li>\n<li><b>Surrogacy</b>: a female of the same or a closely related, more common species carries the embryo of the endangered animal. Example: embryos of the northern white rhinoceros are planned to be carried by southern white rhinoceros females.</li>\n<li><b>Advantages</b>: increases numbers and genetic diversity without moving adult animals. <b>Problems</b>: low success rates, expensive, needs hormone treatment, and few founder animals means little genetic variation.</li></ul>\n<h5>Controlling invasive alien species (18.3.5)</h5>\n<p>An <b>invasive alien species</b> is a species introduced (usually by humans) to an area where it is not native, and which spreads and harms native species.</p>\n<ul><li>They <b>outcompete native species</b>, <b>prey on them</b> (for example rats and cats on islands), or <b>spread disease</b>.</li><li>They can change the habitat and reduce biodiversity, and cause large economic losses (crops, fisheries, waterways). Examples: water hyacinth and <i>Salvinia</i> on tropical lakes; Nile perch in Lake Victoria.</li><li>Control methods: border and quarantine checks, removing the species by hand or poison, biological control with a natural enemy, and educating people not to release or move species.</li></ul>\n<h5>The roles of IUCN and CITES (18.3.6)</h5>\n<ul><li><b>IUCN</b> (International Union for Conservation of Nature): a global network of governments and organisations. It assesses how close each species is to extinction and publishes the <b>Red List</b> (categories such as Vulnerable, Endangered, Critically Endangered, Extinct), advises governments and guides conservation priorities.</li>\n<li><b>CITES</b> (Convention on International Trade in Endangered Species of Wild Fauna and Flora): an agreement between governments that controls or bans <b>international trade</b> in endangered species and their products (ivory, rhino horn, skins, timber). Species are listed in Appendices I to III: Appendix I species may not be traded commercially.</li></ul>","cards":[["Name four causes of extinction.","Climate change, competition (including invasive species), hunting by humans and loss or degradation of habitats."],["What is a frozen zoo?","A store of eggs, sperm, embryos and tissue cells kept in liquid nitrogen (about -196 C) so the genetic material can be used later."],["What is surrogacy in conservation?","A female of the same or a related, more common species carries the embryo of an endangered animal to birth."],["Why are invasive alien species a problem?","They outcompete or prey on native species, spread disease and reduce biodiversity."],["What do IUCN and CITES do?","IUCN assesses extinction risk (Red List) and advises on conservation. CITES controls international trade in endangered species."]]}},"chem":{"2.1":{"notes":"\n<h4>Elements, compounds and mixtures (syllabus 2.1)</h4>\n<table><tr><th></th><th>Element</th><th>Compound</th><th>Mixture</th></tr>\n<tr><td>What it is</td><td>One type of atom only</td><td>Two or more elements chemically bonded together</td><td>Two or more substances not chemically bonded</td></tr>\n<tr><td>Composition</td><td>Fixed</td><td>Fixed ratio of elements (a formula)</td><td>Variable; any proportions</td></tr>\n<tr><td>Properties</td><td>Its own properties</td><td>Different from the elements it contains</td><td>Each part keeps its own properties</td></tr>\n<tr><td>Separation</td><td>Cannot be broken down chemically</td><td>Only by a chemical reaction</td><td>Physical methods (filtering, distillation, magnet)</td></tr>\n<tr><td>Example</td><td>Iron, Fe</td><td>Iron(II) sulfide, FeS</td><td>Iron filings and sulfur</td></tr></table>\n<p>Iron and sulfur mixed together can be separated with a magnet, but heating them makes the compound iron(II) sulfide, which is not magnetic and has new properties.</p>","cards":[["How does a compound differ from a mixture?","A compound has elements chemically bonded in a fixed ratio with new properties; a mixture is not bonded, has any proportions, and can be separated physically."]]}},"bio":{"2.1":{"notes":"\n<h4>New cells come from existing cells (syllabus 2.1.5)</h4>\n<p>New cells are produced by the <b>division of existing cells</b>. In body cells this is <b>mitosis</b>, which makes two genetically identical cells. It allows an organism to grow, replace damaged cells and repair tissue.</p>","cards":[["How are new cells produced?","By the division of existing cells."]]},"3.2":{"notes":"\n<h4>Water as a solvent (syllabus 3.2)</h4>\n<p>Water is a <b>solvent</b>: many substances dissolve in it, so they can be carried and react in solution.</p>\n<ul><li><b>Digestion</b>: enzymes work in solution, and digested food molecules dissolve so they can be absorbed into the blood.</li><li><b>Excretion</b>: urea and excess salts dissolve in water and leave the body in urine.</li><li><b>Transport</b>: blood plasma carries dissolved glucose, ions, urea and hormones; xylem carries dissolved mineral ions.</li></ul>\n<h4>Investigating osmosis (syllabus 3.2)</h4>\n<ul><li><b>Dialysis (Visking) tubing</b>: fill a bag with concentrated sugar solution, tie both ends, dry and weigh it, then place it in water. After a set time, dry and weigh again. The mass increases because water moves in by osmosis through the partially permeable membrane. Repeat with different concentrations.</li>\n<li><b>Potato cylinders</b>: cut identical cylinders, weigh them, and place one in each of several sucrose concentrations. After about 30 minutes, blot dry and weigh. Calculate the percentage change in mass and plot it against concentration. Where the line crosses zero, the solution has the same water potential as the potato cells.</li>\n<li><b>Control variables</b>: same size and mass of tissue, same volume of solution, same temperature and time. Blot each piece in the same way.</li></ul>","cards":[["Give three roles of water as a solvent in organisms.","In digestion (food dissolves to be absorbed), excretion (urea dissolves in urine) and transport (plasma and xylem carry dissolved substances)."],["How can osmosis be investigated with potato cylinders?","Weigh cylinders, leave them in different sucrose solutions, blot and reweigh, then plot the percentage change in mass against concentration."]]}}};
function gapApply(l,subj,u,j){const g=(GAP[subj]||{})[u+"."+j];if(!g)return;if(!/data-gap="1"/.test(l.notes||""))l.notes=(l.notes||"")+g.notes.replace(/<h4>/,'<h4 data-gap="1">');const have=new Set((l.cards||[]).map(c=>String(c[0]).toLowerCase()));(g.cards||[]).forEach(c=>{if(!have.has(c[0].toLowerCase())){l.cards=l.cards||[];l.cards.push(c)}})}
window.GAPFILL=gapApply;
window.GAPALL=k=>{const S=SUBJ[k];if(S)S.units.forEach(u=>(u.lessons||[]).forEach((l,j)=>gapApply(l,k,u.n,j+1)))};Object.keys(SUBJ).forEach(k=>window.GAPALL(k));
function sylBlock(l,k){
  const L0=(SYL[k]||{})[l.u.n+"."+(l.idx+1)];if(!L0||!L0.length)return"";
  const esc=s=>String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;");
  return `<details class="syl"><summary>Syllabus objectives for this lesson (${L0.length})</summary><ul>${L0.map(o=>`<li><b>${esc(o[0])}</b> ${esc(o[1])}${o[2]?' <span class="sylx">Supplement</span>':""}</li>`).join("")}</ul></details>`;
}
